/// matters — what applying it writes back into the page.
#[cfg(test)]
mod wrap_hyphen_tests;

/// The editor's blank glyphs: a letter the document's embedded subset maps but
/// never drew must come out in the program's own face, not as nothing.
#[cfg(test)]
mod editor_blank_glyph_tests {
    use super::*;
    use eframe::App as _;
    use egui_kittest::Harness;

    // -- splitting a buffer by what the face can draw ----------------------

    fn all_but_b(c: char) -> bool {
        c != 'b'
    }

    #[test]
    fn a_letter_the_face_cannot_draw_gets_a_section_of_its_own() {
        assert_eq!(
            editor_sections("a b a", &all_but_b),
            vec![(0..2, true), (2..3, false), (3..5, true)],
            "the space after `a` stays with the document's face; `b` is on its own"
        );
    }

    #[test]
    fn neighbouring_uncovered_letters_share_a_section() {
        assert_eq!(editor_sections("abba", &all_but_b), vec![(0..1, true), (1..3, false), (3..4, true)]);
    }

    /// Whitespace is drawable, so a space between two uncovered letters is the
    /// document's, not the fallback's — a line is not cut into a section per
    /// word just because every word has a `b`.
    #[test]
    fn whitespace_counts_as_covered_even_between_uncovered_letters() {
        assert_eq!(editor_sections("b b", &all_but_b), vec![(0..1, false), (1..2, true), (2..3, false)]);
        assert_eq!(editor_sections("  \t", &|_| false), vec![(0..3, true)], "nothing but whitespace is all drawable");
    }

    #[test]
    fn a_line_with_nothing_to_move_is_one_section() {
        assert_eq!(editor_sections("abc def", &|_| true), vec![(0..7, true)]);
        assert_eq!(editor_sections("bbb", &all_but_b), vec![(0..3, false)]);
        assert_eq!(editor_sections("", &all_but_b), vec![]);
    }

    /// The ranges are byte ranges and must fall on character boundaries.
    #[test]
    fn multi_byte_characters_are_not_cut_in_half() {
        // "é" is two bytes, "ü" two.
        assert_eq!(editor_sections("é b ü", &all_but_b), vec![(0..3, true), (3..4, false), (4..7, true)]);
        for text in ["é b ü", "日本 b 語", "b\nb", "a b a", ""] {
            let sections = editor_sections(text, &all_but_b);
            let tiled: String = sections.iter().map(|(range, _)| &text[range.clone()]).collect();
            assert_eq!(tiled, text, "the sections must tile {text:?} exactly");
        }
    }

    // -- the job the editor lays out ---------------------------------------

    fn doc_format() -> egui::TextFormat {
        egui::TextFormat {
            font_id: egui::FontId::new(12.0, egui::FontFamily::Name(RUN_FAMILY.into())),
            color: egui::Color32::BLACK,
            ..Default::default()
        }
    }

    fn fallback_format() -> egui::TextFormat {
        egui::TextFormat {
            font_id: egui::FontId::proportional(12.0),
            color: egui::Color32::BLACK,
            ..Default::default()
        }
    }

    /// The slice of a job's text a section covers.
    fn text_of<'a>(job: &'a egui::text::LayoutJob, section: &egui::text::LayoutSection) -> &'a str {
        &job.text[section.byte_range.start.0..section.byte_range.end.0]
    }

    /// Each section of a job as `(its text, whether it is the document's face)`.
    fn sections_of(job: &egui::text::LayoutJob) -> Vec<(String, bool)> {
        job.sections
            .iter()
            .map(|s| {
                let is_doc = s.format.font_id.family == egui::FontFamily::Name(RUN_FAMILY.into());
                (text_of(job, s).to_string(), is_doc)
            })
            .collect()
    }

    /// **The job's text is the buffer, exactly, whatever the split** — the
    /// cursor and the selection are positions in the buffer — and the letters
    /// the face cannot draw are in the other face. Checked for a justified
    /// paragraph and for plain text, and with newlines, doubled and trailing
    /// spaces, and a line that is only an uncovered letter.
    #[test]
    fn the_job_text_is_the_buffer_and_the_uncovered_letters_use_the_other_face() {
        let (doc, fallback) = (doc_format(), fallback_format());
        for text in ["abc bab\nb\nlast b line", "bb  b \n\n b", "abc"] {
            for justify in [false, true] {
                let job = editor_layout_job(text, justify, 200.0, &doc, &fallback, &all_but_b, &mut |w| {
                    w.chars().count() as f32 * 6.0
                });
                assert_eq!(job.text, text, "the job's text drifted from the buffer (justify {justify})");
                let sections = sections_of(&job);
                assert_eq!(
                    sections.iter().map(|(t, _)| t.as_str()).collect::<String>(),
                    text,
                    "the sections must tile the text"
                );
                for (piece, is_doc) in &sections {
                    // A section in the other face holds uncovered letters only;
                    // one in the document's face holds none.
                    assert_eq!(
                        piece.contains('b'),
                        !is_doc,
                        "{piece:?} is in the wrong face (justify {justify}, text {text:?})"
                    );
                }
            }
        }
        // And there really are two fonts in a buffer that has the letter.
        let job = editor_layout_job("abc bab", false, 200.0, &doc, &fallback, &all_but_b, &mut |_| 0.0);
        let families: std::collections::HashSet<_> =
            job.sections.iter().map(|s| s.format.font_id.family.clone()).collect();
        assert_eq!(families.len(), 2, "one face for the letters it can draw, one for the rest");
        // Same size and colour in both.
        assert!(job.sections.iter().all(|s| s.format.font_id.size == 12.0 && s.format.color == egui::Color32::BLACK));
    }

    /// What a job comes to, section by section — text, extra space before it,
    /// font and colour — for comparing two jobs. (`LayoutJob::append` merges
    /// neighbouring sections that look alike, so the number of sections is
    /// not something to assert; what they say is.)
    fn shape_of(job: &egui::text::LayoutJob) -> (String, Vec<(String, f32, egui::FontId, egui::Color32)>) {
        (
            job.text.clone(),
            job.sections
                .iter()
                .map(|s| (text_of(job, s).to_string(), s.leading_space, s.format.font_id.clone(), s.format.color))
                .collect(),
        )
    }

    /// The layouter's job exactly as it was built before the document's face
    /// was split by coverage — the old loop, copied here to prove that the
    /// common path (nothing uncovered) comes out the same.
    fn the_job_as_it_was(
        text: &str,
        justify: bool,
        wrap_width: f32,
        format: &egui::TextFormat,
        mut measure: impl FnMut(&str) -> f32,
    ) -> egui::text::LayoutJob {
        let mut job = egui::text::LayoutJob::default();
        let lines: Vec<&str> = text.split('\n').collect();
        let last = lines.len().saturating_sub(1);
        for (li, line) in lines.iter().enumerate() {
            if li > 0 {
                job.append("\n", 0.0, format.clone());
            }
            let tokens: Vec<&str> = line.split_inclusive(' ').collect();
            if !justify || li == last || tokens.len() < 2 {
                job.append(line, 0.0, format.clone());
                continue;
            }
            let widths: Vec<f32> = tokens.iter().map(|t| measure(t.trim_end())).collect();
            let gaps = justify_gaps(&widths, wrap_width);
            for (token, extra) in tokens.iter().zip(gaps) {
                job.append(token, extra, format.clone());
            }
        }
        job
    }

    /// **With nothing uncovered the job is what it always was**, justified or
    /// not: the same text, and the same sections, in the same face, with the
    /// same stretch before each word.
    #[test]
    fn a_buffer_with_nothing_to_move_is_laid_out_as_it_always_was() {
        let (doc, fallback) = (doc_format(), fallback_format());
        let measure = |w: &str| w.chars().count() as f32 * 6.5;
        for text in [
            "abc def\nxyz",
            "one two three\nfour five six\nseven",
            "",
            "a",
            "  lead and  double  \n\ntrail ",
        ] {
            for justify in [false, true] {
                let now = editor_layout_job(text, justify, 180.0, &doc, &fallback, &|_| true, &mut { measure });
                let then = the_job_as_it_was(text, justify, 180.0, &doc, measure);
                assert_eq!(shape_of(&now), shape_of(&then), "changed for {text:?} (justify {justify})");
            }
        }
        // And a justified line really was stretched in what is being compared.
        let stretched = the_job_as_it_was("one two three\nlast", true, 180.0, &doc, measure);
        assert!(stretched.sections.iter().any(|s| s.leading_space > 0.0), "setup: nothing was stretched");
    }

    /// **Justification is untouched**: the stretch a word gets is still put
    /// before it, and when that word is split by an uncovered letter the
    /// stretch goes before the *first* piece only.
    #[test]
    fn the_stretch_of_a_justified_word_goes_before_its_first_piece_only() {
        let (doc, fallback) = (doc_format(), fallback_format());
        // "abc" measures 24 and "bab" 18: 42 of 100 used, so 58 is the one gap's.
        let job = editor_layout_job("abc bab\nz", true, 100.0, &doc, &fallback, &all_but_b, &mut |w| {
            w.chars().count() as f32 * if w == "abc" { 8.0 } else { 6.0 }
        });
        let stretched: Vec<(String, f32)> = job
            .sections
            .iter()
            .filter(|s| s.leading_space != 0.0)
            .map(|s| (text_of(&job, s).to_string(), s.leading_space))
            .collect();
        assert_eq!(
            stretched,
            vec![("b".to_string(), 58.0)],
            "exactly one section is stretched: the first piece of the second word"
        );
        // The same stretch as the old, unsplit layout puts before that word.
        let then = the_job_as_it_was("abc bab\nz", true, 100.0, &doc, |w| {
            w.chars().count() as f32 * if w == "abc" { 8.0 } else { 6.0 }
        });
        let before_then: Vec<f32> = then.sections.iter().map(|s| s.leading_space).filter(|l| *l != 0.0).collect();
        assert_eq!(before_then, vec![58.0]);
    }

    // -- a real face with a real hole in it --------------------------------

    /// The bundled Montserrat Regular with the outline of `c` emptied — the
    /// way a subsetter leaves a glyph nothing drew: its `loca` entry made equal
    /// to the next one. `cmap` and every advance width are untouched, so the
    /// face still maps `c` and still gives it a width.
    ///
    /// This crate has no font parser, so which glyph that is comes from asking
    /// `outlined_chars` (tested in `pdf_core` on its own): the glyph whose
    /// emptying uncovers `c`.
    fn montserrat_without_ink_for(c: char) -> Vec<u8> {
        let font = BUNDLED_OUTLINED_FONTS[0];
        let u16_at = |at: usize| u16::from_be_bytes([font[at], font[at + 1]]) as usize;
        let u32_at = |at: usize| u32::from_be_bytes([font[at], font[at + 1], font[at + 2], font[at + 3]]) as usize;
        let table = |tag: &[u8; 4]| -> usize {
            (0..u16_at(4))
                .map(|i| 12 + 16 * i)
                .find(|&at| &font[at..at + 4] == tag)
                .map(|at| u32_at(at + 8))
                .unwrap_or_else(|| panic!("no {} table", String::from_utf8_lossy(tag)))
        };
        let (head, loca, maxp) = (table(b"head"), table(b"loca"), table(b"maxp"));
        let glyphs = u16_at(maxp + 4);
        let width = if u16_at(head + 50) != 0 { 4 } else { 2 };
        for glyph in 0..glyphs {
            let mut candidate = font.to_vec();
            let (from, to) = (loca + width * (glyph + 1), loca + width * glyph);
            let next = candidate[from..from + width].to_vec();
            candidate[to..to + width].copy_from_slice(&next);
            let coverage = pdf_core::pdf::embed::outlined_chars(&candidate).expect("still a face");
            if !coverage.has(c) {
                return candidate;
            }
        }
        panic!("no glyph of Montserrat gives {c:?} its ink");
    }

    /// **The premise behind reading symbol subtables in `outlined_chars`.** egui
    /// draws a face whose letters sit in a Windows symbol `cmap` — its shaper
    /// prefers that subtable over all others — so a coverage that called such a
    /// face blank would move text egui draws perfectly well into the fallback
    /// face. Montserrat with every `cmap` record rewritten as platform 3,
    /// encoding 0: the letters are still found by egui, with ink, and the
    /// coverage agrees.
    #[test]
    fn egui_draws_a_symbol_encoded_face_and_the_coverage_agrees() {
        let font = BUNDLED_OUTLINED_FONTS[0];
        let u16_at = |at: usize| u16::from_be_bytes([font[at], font[at + 1]]) as usize;
        let u32_at = |at: usize| u32::from_be_bytes([font[at], font[at + 1], font[at + 2], font[at + 3]]) as usize;
        let cmap = (0..u16_at(4))
            .map(|i| 12 + 16 * i)
            .find(|&at| &font[at..at + 4] == b"cmap")
            .map(|at| u32_at(at + 8))
            .expect("a cmap table");
        let mut symbol = font.to_vec();
        for i in 0..u16_at(cmap + 2) {
            let at = cmap + 4 + 8 * i;
            symbol[at..at + 2].copy_from_slice(&3u16.to_be_bytes());
            symbol[at + 2..at + 4].copy_from_slice(&0u16.to_be_bytes());
        }

        let mut job = egui::text::LayoutJob::default();
        job.append("abc", 0.0, doc_format());
        let galley = laid_out_in(symbol.clone(), job);
        assert_eq!(
            ink_by_char(&galley),
            [('a', true), ('b', true), ('c', true)],
            "egui should draw letters from a symbol-encoded face"
        );
        let coverage = pdf_core::pdf::embed::outlined_chars(&symbol).expect("a face");
        assert!(coverage.has('a') && coverage.has('b') && coverage.has('c'));
    }

    #[test]
    fn the_test_face_is_what_it_claims_to_be() {
        let gutted = montserrat_without_ink_for('b');
        assert!(pdf_core::pdf::embed::can_spell(&gutted, "abc"), "the face still maps every letter");
        let coverage = pdf_core::pdf::embed::outlined_chars(&gutted).expect("a face");
        assert!(!coverage.has('b'));
        assert!(coverage.has('a') && coverage.has('c'));
    }

    /// Runs `layout` in a frame of a fresh context whose run face is `face`.
    ///
    /// The harness settles a few frames as it is built, before the face can be
    /// installed, and a family that is not bound yet panics rather than falls
    /// back — see `install_fonts` — so nothing is laid out until the face has
    /// been handed over and a frame has begun with it.
    fn in_a_frame_with_run_face<R>(face: Vec<u8>, mut layout: impl FnMut(&mut egui::Ui) -> R) -> R {
        let installed = std::cell::Cell::new(false);
        let mut result = None;
        let mut h = Harness::new_ui(|ui: &mut egui::Ui| {
            if installed.get() {
                result = Some(layout(ui));
            }
        });
        install_fonts(&h.ctx, Some(face));
        installed.set(true);
        h.run_steps(3);
        drop(h);
        result.expect("a frame ran with the face installed")
    }

    /// Lays `job` out in a fresh context whose run face is `face`.
    fn laid_out_in(face: Vec<u8>, job: egui::text::LayoutJob) -> std::sync::Arc<egui::Galley> {
        in_a_frame_with_run_face(face, |ui| ui.fonts_mut(|f| f.layout_job(job.clone())))
    }

    /// Which of a galley's glyphs have something to draw, by character.
    fn ink_by_char(galley: &egui::Galley) -> Vec<(char, bool)> {
        galley
            .rows
            .iter()
            .flat_map(|row| row.glyphs.iter())
            .filter(|g| !g.chr.is_whitespace())
            .map(|g| (g.chr, !g.uv_rect.is_nothing()))
            .collect()
    }

    /// **The bug, in egui's own terms.** In the document's face alone a letter
    /// the subset has no outline for is *found* — and drawn as nothing; the
    /// two-face job draws it. Without the first half this would prove only that
    /// the second half runs.
    #[test]
    fn egui_draws_a_blank_for_the_missing_letter_and_the_two_face_job_draws_it() {
        let gutted = montserrat_without_ink_for('b');
        let (doc, fallback) = (doc_format(), fallback_format());

        // As the editor used to lay it out: everything in the document's face.
        let mut old = egui::text::LayoutJob::default();
        old.append("abc bab", 0.0, doc.clone());
        let before = ink_by_char(&laid_out_in(gutted.clone(), old));
        assert_eq!(
            before,
            [('a', true), ('b', false), ('c', true), ('b', false), ('a', true), ('b', false)],
            "the document's face alone should draw nothing for b"
        );

        // As it lays it out now.
        let coverage = pdf_core::pdf::embed::outlined_chars(&gutted).expect("a face");
        let covered = |c: char| coverage.has(c);
        let job = editor_layout_job("abc bab", false, 200.0, &doc, &fallback, &covered, &mut |_| 0.0);
        let galley = laid_out_in(gutted, job);
        let after = ink_by_char(&galley);
        assert_eq!(
            after,
            [('a', true), ('b', true), ('c', true), ('b', true), ('a', true), ('b', true)],
            "every letter should have ink now, the b among them"
        );
        assert_eq!(galley.job.text, "abc bab", "the galley is of exactly the buffer");
        // Both faces share one baseline: the fallback `b` sits on the same line
        // as its neighbours rather than riding above or below them.
        let baselines: std::collections::BTreeSet<i32> =
            galley.rows.iter().flat_map(|row| row.glyphs.iter()).map(|g| (g.pos.y * 100.0).round() as i32).collect();
        assert_eq!(baselines.len(), 1, "the two faces are on different baselines: {baselines:?}");
    }

    /// A job with nothing uncovered measures the same as the plain call it
    /// replaced — the justification inputs are unchanged for every word that
    /// does not have a missing letter.
    #[test]
    fn a_word_measures_the_same_through_the_job_as_through_layout_no_wrap() {
        let (doc, fallback) = (doc_format(), fallback_format());
        let (plain, sectioned) = in_a_frame_with_run_face(BUNDLED_OUTLINED_FONTS[0].to_vec(), |ui| {
            let plain = ui
                .fonts_mut(|f| f.layout_no_wrap("accept".to_string(), doc.font_id.clone(), egui::Color32::BLACK))
                .size()
                .x;
            let mut job = egui::text::LayoutJob::default();
            append_sectioned(&mut job, "accept", 0.0, &doc, &fallback, &|_| true);
            (plain, ui.fonts_mut(|f| f.layout_job(job)).size().x)
        });
        assert!(plain > 10.0, "setup: the word has a real width ({plain})");
        assert_eq!(plain, sectioned);
    }

    // -- the whole editor ---------------------------------------------------

    /// A one-page PDF drawing `words` in an embedded copy of `font` — written
    /// the way the editing path embeds a whole face, so the page's own font is
    /// the gutted one, as a producer's subset would be.
    fn pdf_embedding(font: &[u8], words: &str) -> Vec<u8> {
        let embedded = pdf_core::pdf::embed::truetype(font, 5).expect("the face embeds");
        let content = format!("BT /F3 12 Tf 100 700 Td ({words}) Tj ET\n");
        let mut objects: Vec<(u32, Vec<u8>)> = vec![
            (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
            (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec()),
            (
                3,
                format!(
                    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R \
                     /Resources << /Font << /F3 {} 0 R >> >> >>",
                    embedded.font
                )
                .into_bytes(),
            ),
            (4, format!("<< /Length {} >>\nstream\n{content}endstream", content.len()).into_bytes()),
        ];
        objects.extend(embedded.objects.iter().cloned());
        objects.sort_by_key(|(number, _)| *number);
        let mut out = b"%PDF-1.4\n".to_vec();
        let mut offsets = std::collections::BTreeMap::new();
        for (number, body) in &objects {
            offsets.insert(*number, out.len());
            out.extend_from_slice(format!("{number} 0 obj\n").as_bytes());
            out.extend_from_slice(body);
            out.extend_from_slice(b"\nendobj\n");
        }
        let size = objects.last().map(|(number, _)| number + 1).expect("objects");
        let xref_at = out.len();
        out.extend_from_slice(format!("xref\n0 {size}\n0000000000 65535 f \n").as_bytes());
        for number in 1..size {
            out.extend_from_slice(format!("{:010} 00000 n \n", offsets[&number]).as_bytes());
        }
        out.extend_from_slice(
            format!("trailer\n<< /Size {size} /Root 1 0 R >>\nstartxref\n{xref_at}\n%%EOF").as_bytes(),
        );
        out
    }

    fn galleys_in(shape: &egui::Shape, found: &mut Vec<std::sync::Arc<egui::Galley>>) {
        match shape {
            egui::Shape::Text(text) => found.push(text.galley.clone()),
            egui::Shape::Vec(shapes) => shapes.iter().for_each(|s| galleys_in(s, found)),
            _ => {}
        }
    }

    /// The editor open on a one-line page whose embedded face has no ink for
    /// `b`, drawn for a few frames — the face installed, then in use.
    fn editor_on_a_gutted_page(name: &str) -> Harness<'static, PagifyApp> {
        let dir = std::env::temp_dir().join("pagify-app-tests");
        std::fs::create_dir_all(&dir).expect("scratch dir");
        let path = dir.join(format!("blank-glyph-{name}.pdf"));
        std::fs::write(&path, pdf_embedding(&montserrat_without_ink_for('b'), "abc bab")).expect("write the page");
        let app = PagifyApp::new(Some(&path.to_string_lossy()));
        assert!(app.tab().doc.is_some(), "the synthetic page did not open");
        let mut h = Harness::builder().with_size(egui::vec2(1400.0, 1000.0)).build_ui_state(
            |ui, app: &mut PagifyApp| {
                let mut frame = eframe::Frame::_new_kittest();
                app.ui(ui, &mut frame);
            },
            app,
        );
        h.run_steps(4);
        let run = h
            .state_mut()
            .tab()
            .doc
            .as_ref()
            .expect("open")
            .session
            .text_runs(0)
            .expect("runs")
            .into_iter()
            .find(|r| r.text.contains("abc"))
            .expect("the line");
        let at = AppPoint {
            x: ((run.rect.left + run.rect.right) / 2.0) as f64,
            y: ((run.rect.top + run.rect.bottom) / 2.0) as f64,
        };
        h.state_mut().pick_text_run(0, at).expect("a run was here");
        // One frame installs the face, the next marks it usable, then it draws.
        h.run_steps(5);
        h
    }

    /// **The reported case, on the real file: a heading's embedded subset has
    /// no ink for b, f, j, k, q or z, and the editor opened on it drew those
    /// letters as nothing.** Picks a heading near the top of the Marina mall
    /// datasheet whose own face lacks them, types all six into the editor, and
    /// reads what egui painted. Measured before this change on this very face:
    /// `b f j k q z` all without ink.
    ///
    /// Skipped, with a note, where the file is not on this machine.
    #[test]
    fn on_the_real_datasheet_the_letters_a_heading_face_never_drew_come_out() {
        let path = r"C:\Users\hsili\Desktop\Datasheets - Editors market - Marina mall.pdf";
        let app = PagifyApp::new(Some(path));
        if app.tab().doc.is_none() {
            eprintln!("skipping: Marina mall datasheet not present on this machine");
            return;
        }
        let mut h = Harness::builder().with_size(egui::vec2(1400.0, 1000.0)).build_ui_state(
            |ui, app: &mut PagifyApp| {
                let mut frame = eframe::Frame::_new_kittest();
                app.ui(ui, &mut frame);
            },
            app,
        );
        h.run_steps(4);

        // A run near the top of the page (so the editor is on screen) set in a
        // face that has no b, no f and no z but does have a and e.
        let heading = {
            let session = &h.state().tab().doc.as_ref().expect("open").session;
            session
                .text_runs(0)
                .expect("runs")
                .into_iter()
                .filter(|r| r.text.trim().chars().count() >= 6 && r.rect.top < 250.0)
                .find(|r| {
                    session
                        .run_font_data(0, r.object)
                        .ok()
                        .flatten()
                        .and_then(|bytes| pdf_core::pdf::embed::outlined_chars(&bytes))
                        .is_some_and(|c| !c.has('b') && !c.has('f') && !c.has('z') && c.has('a') && c.has('e'))
                })
                .expect("a run in a face that lacks b and f — has the file changed?")
        };
        let at = AppPoint {
            x: ((heading.rect.left + heading.rect.right) / 2.0) as f64,
            y: ((heading.rect.top + heading.rect.bottom) / 2.0) as f64,
        };
        h.state_mut().pick_text_run(0, at).expect("picked the heading");
        // The paragraph around it may be set mostly in another face; the case
        // being tested is the heading's own face in the editor.
        h.state_mut().want_document_face(0, heading.object);
        let words = "bfjkqz abc bfjkqz";
        h.state_mut().tab_mut().editing_run.as_mut().expect("editing").buffer = words.to_string();
        h.run_steps(6);
        assert!(h.state().editor_face_ready, "setup: the heading's face should be in use");

        let mut galleys = Vec::new();
        for clipped in &h.output().shapes {
            galleys_in(&clipped.shape, &mut galleys);
        }
        let galley = galleys.iter().find(|g| g.job.text == words).expect("the editor's painted text");
        assert!(
            ink_by_char(galley).iter().all(|(c, ink)| *ink || !c.is_alphabetic()),
            "a letter the heading's face never drew was painted as nothing: {:?}",
            ink_by_char(galley)
        );
    }

    /// **Picking a run reads which letters its face can draw — once.** The
    /// face is the page's, so what it lacks is the page's gap, not the
    /// program's.
    #[test]
    fn picking_a_run_reads_the_coverage_of_its_face_once() {
        let mut h = editor_on_a_gutted_page("coverage");
        let first = h.state().editor_face_coverage.clone().expect("the face's coverage should have been read");
        assert!(!first.has('b'), "the page's face has no ink for b");
        assert!(first.has('a') && first.has('c'));

        // Picking again — the same face — must not read it all over again.
        let run = h.state().tab().editing_run.as_ref().expect("editing").clone();
        let at = AppPoint {
            x: ((run.rect.left + run.rect.right) / 2.0) as f64,
            y: ((run.rect.top + run.rect.bottom) / 2.0) as f64,
        };
        h.state_mut().tab_mut().editing_run = None;
        h.state_mut().pick_text_run(0, at).expect("picked again");
        let second = h.state().editor_face_coverage.clone().expect("still there");
        assert!(std::sync::Arc::ptr_eq(&first, &second), "the same face was read a second time");
    }

    /// **The editor, opened on that page, draws the letter its face lacks.**
    /// The galley egui painted for the box is of exactly the buffer, every
    /// letter in it has ink — the `b`s too — and it is made of two fonts.
    #[test]
    fn the_open_editor_draws_ink_for_a_letter_its_face_never_drew() {
        let h = editor_on_a_gutted_page("editor");
        let buffer = h.state().tab().editing_run.as_ref().expect("editing").buffer.clone();
        assert_eq!(buffer, "abc bab", "setup: the page's own words");
        assert!(h.state().editor_face_ready, "setup: the document's face should be installed and in use");

        let mut galleys = Vec::new();
        for clipped in &h.output().shapes {
            galleys_in(&clipped.shape, &mut galleys);
        }
        let galley = galleys
            .iter()
            .find(|g| g.job.text == buffer)
            .unwrap_or_else(|| panic!("no painted text is the buffer {buffer:?}; saw {:?}", galleys.iter().map(|g| g.job.text.clone()).collect::<Vec<_>>()));

        assert_eq!(
            ink_by_char(galley),
            [('a', true), ('b', true), ('c', true), ('b', true), ('a', true), ('b', true)],
            "the editor drew nothing for a letter the page's face never drew"
        );
        let families: std::collections::HashSet<_> =
            galley.job.sections.iter().map(|s| s.format.font_id.family.clone()).collect();
        assert!(families.contains(&egui::FontFamily::Name(RUN_FAMILY.into())), "the page's face was not used at all");
        assert!(families.contains(&egui::FontFamily::Proportional), "nothing was laid out in the other face");
    }
}

/// What applying an edit does to a paragraph: **a retyped line replaces its
/// pieces** (the first takes the words, the others come off the page), a line
/// the edit does not change is left exactly as it was — every piece of it — a
/// frozen line is never touched, a paragraph that no longer lines up with its
/// own text is refused rather than guessed at, and the whole apply undoes, and
/// redoes, as one exact step.
#[cfg(test)]
mod paragraph_apply_tests {
    use super::tests_support::{assert_page_after, picture, runs_in_order, same_picture, same_run, squeeze};
    use super::wrap_hyphen_tests::open_page;
    use super::*;
    use pdf_core::document::{Color, Rect, TextLineEdit, TextRun};

    // -- on a page ----------------------------------------------------------

    fn said(app: &PagifyApp) -> String {
        app.cmd.history().iter().map(|e| e.text.as_str()).collect::<Vec<_>>().join("\n")
    }

    /// Every text object of page 1 with the words and colour it has now.
    fn runs_by_object(app: &PagifyApp) -> std::collections::HashMap<usize, (String, Color)> {
        app.tab()
            .doc
            .as_ref()
            .expect("open")
            .session
            .text_runs(0)
            .expect("runs")
            .into_iter()
            .map(|r| (r.object, (r.text, r.color)))
            .collect()
    }

    /// Arms Edit Text and clicks the middle of text object `object`.
    fn pick_object(app: &mut PagifyApp, object: usize) {
        let run = app
            .tab()
            .doc
            .as_ref()
            .expect("open")
            .session
            .text_runs(0)
            .expect("runs")
            .into_iter()
            .find(|r| r.object == object)
            .expect("the object is on the page");
        let at = AppPoint {
            x: ((run.rect.left + run.rect.right) / 2.0) as f64,
            y: ((run.rect.top + run.rect.bottom) / 2.0) as f64,
        };
        app.submit("edittext");
        app.pick_text_run(0, at).expect("a run was here");
    }

    /// A page of `rows`, each `(left piece, right piece)`, one 12 pt below the
    /// last; the right piece starts 3 pt after the left one ends — as a
    /// justified line a producer cut at a word gap is. Objects are in drawing
    /// order: row 0's left piece is object 0 and its right piece object 1,
    /// row 1's are 2 and 3, and so on.
    pub(super) fn two_piece_page(name: &str, rows: &[(&str, &str)]) -> PagifyApp {
        let ys: Vec<f32> = (0..rows.len()).map(|i| 700.0 - 12.0 * i as f32).collect();
        // The left pieces alone first, to measure where each one ends: the gap
        // is measured, not typed.
        let lefts: Vec<(f32, f32, &str)> =
            rows.iter().zip(&ys).map(|((left, _), y)| (100.0, *y, *left)).collect();
        let probe = open_page(&format!("{name}-probe"), &lefts, "");
        let measured = runs_by_object(&probe);
        let right_edges: Vec<f32> = (0..rows.len())
            .map(|i| {
                probe
                    .tab()
                    .doc
                    .as_ref()
                    .expect("open")
                    .session
                    .text_run_at(0, i)
                    .expect("asked")
                    .expect("the left piece")
                    .rect
                    .right
            })
            .collect();
        assert_eq!(measured.len(), rows.len(), "setup: one object per left piece");
        let mut pieces: Vec<(f32, f32, &str)> = Vec::new();
        for (i, (left, right)) in rows.iter().enumerate() {
            pieces.push((100.0, ys[i], *left));
            pieces.push((right_edges[i] + 3.0, ys[i], *right));
        }
        open_page(name, &pieces, "")
    }

    const ROWS: [(&str, &str); 5] = [
        ("Lorem ipsum dolor ", "sit amet consectetur"),
        ("adipiscing elit sed ", "do eiusmod tempor"),
        ("incididunt ut labore ", "et dolore magna"),
        ("aliqua ut enim ad ", "minim veniam quis"),
        ("nostrud exercitation ", "ullamco laboris nisi"),
    ];

    /// A five-line, two-pieces-a-line paragraph opened for editing, with one
    /// word of the third line retyped in the buffer — not applied yet. Returns
    /// what the page reads now, the editor as picked, and the new third line.
    fn five_lines_with_a_word_retyped(name: &str) -> (PagifyApp, Vec<TextRun>, EditingRun, String) {
        let mut app = two_piece_page(name, &ROWS);
        pick_object(&mut app, 4);
        let edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 5, "setup: the five rows should be one paragraph: {:?}", edit.buffer);
        assert!(
            edit.lines.iter().all(|(objects, _)| objects.len() == 2),
            "setup: every line should be its two pieces: {:?}",
            edit.lines
        );
        assert_eq!(edit.frozen, vec![false; 5], "setup: nothing picked from text alone is frozen");

        let before = runs_in_order(&app);
        let retyped = edit.buffer.replace("labore", "LABORE");
        assert_ne!(retyped, edit.buffer, "setup: the word is in the buffer");
        // Whatever the two pieces of the third line join to — the extracted
        // text of a piece does not always keep the space the producer put at
        // its end — with the one word changed.
        let new_third = retyped.split('\n').nth(2).expect("a third line").to_string();
        assert!(new_third.contains("LABORE") && new_third.contains("dolore magna"), "{new_third:?}");
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped;
        (app, before, edit, new_third)
    }

    /// **Editing one word leaves every other line exactly as it was, and the
    /// retyped line REPLACES its pieces.** A five-line paragraph, every line cut
    /// in two pieces by a 3 pt gap — the way a justified column is — and one word
    /// retyped in the third. The third line is now its first piece, holding the
    /// new words; its second piece is *gone from the page* (not painted in the
    /// page's colour, which left the old words in the file and let the painted
    /// piece erase part of the new ones); the page has lost exactly that one
    /// object; and the four lines nobody touched keep their own words, colour and
    /// place.
    #[test]
    fn editing_one_word_leaves_every_other_two_piece_line_exactly_as_it_was() {
        let (mut app, before, edit, new_third) = five_lines_with_a_word_retyped("five-lines");
        app.apply_editing_page();
        let after = runs_in_order(&app);

        let (first, second) = (edit.lines[2].0[0], edit.lines[2].0[1]);
        assert_page_after("one word of line 3", &before, &after, &[(first, &new_third)], &[second]);
        assert!(said(&app).contains("paragraph changed"), "{}", said(&app));
    }

    const FOUR: [(f32, f32, &str); 4] = [
        (100.0, 700.0, "first line of the words"),
        (100.0, 688.0, "second line of the words"),
        (100.0, 676.0, "third line of the words"),
        (100.0, 664.0, "fourth line of the words"),
    ];

    /// The four-line paragraph opened for editing, then rebuilt white-box into
    /// the shape a block with drawn words in it has:
    ///
    /// * line 0 — the first line, ordinary;
    /// * line 1 — **nothing at all**: a whole line drawn as shapes, frozen,
    ///   with no text object;
    /// * line 2 — the second line, **frozen**: its text objects share the line
    ///   with outlined words;
    /// * lines 3 and 4 — the third and fourth, ordinary.
    ///
    /// Objects 0 to 3 are the four lines in order.
    fn a_paragraph_with_frozen_lines(name: &str) -> (PagifyApp, EditingRun) {
        let mut app = open_page(name, &FOUR, "");
        pick_object(&mut app, 0);
        let mut edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 4, "setup: the four lines should be one paragraph: {:?}", edit.buffer);
        let lines = edit.lines.clone();
        let gap = Rect {
            left: lines[0].1.left,
            top: lines[0].1.bottom,
            right: lines[0].1.right,
            bottom: lines[0].1.bottom,
        };
        edit.lines = vec![lines[0].clone(), (Vec::new(), gap), lines[1].clone(), lines[2].clone(), lines[3].clone()];
        edit.frozen = vec![false, true, true, false, false];
        edit.original = format!(
            "{}\n\n{}\n{}\n{}",
            FOUR[0].2, FOUR[1].2, FOUR[2].2, FOUR[3].2
        );
        edit.buffer = edit.original.clone();
        (app, edit)
    }

    /// **A frozen line is never touched by an apply, and nothing panics** — a
    /// line with no text object at all in the middle of the paragraph, and a
    /// frozen line that has one, with words typed over both and real changes
    /// on the lines around them.
    #[test]
    fn frozen_lines_are_never_touched_by_an_apply_and_nothing_panics() {
        let (mut app, mut edit) = a_paragraph_with_frozen_lines("frozen-middle");
        let (a, b, c, d) = (edit.lines[0].0[0], edit.lines[2].0[0], edit.lines[3].0[0], edit.lines[4].0[0]);
        edit.buffer = "first LINE of the words\ntyped over the empty frozen line\nsecond line TYPED OVER\n\
                       third LINE of the words\nfourth line of the words"
            .to_string();
        // Every line here is one piece, so nothing comes off the page and no
        // object number moves — the ids below stay good through the apply.

        // The commands first: one replace holding exactly the two real changes,
        // and nothing that reaches the frozen line's object (b) or the line
        // nobody touched (d) — neither retyped nor removed.
        let planned = app.paragraph_edit_commands(&edit, &edit.buffer).expect("it lines up");
        let [pdf_core::command::Command::ReplaceTextLines { edits, .. }] = planned.commands.as_slice() else {
            panic!("one replace and nothing else was expected: {:?}", planned.commands)
        };
        let written: Vec<(usize, String, Vec<usize>)> = edits
            .iter()
            .map(|edit| match edit {
                TextLineEdit::Retype { first, text, remove, .. } => (*first, text.clone(), remove.clone()),
                other => panic!("unexpected edit: {other:?}"),
            })
            .collect();
        assert_eq!(
            written,
            [
                (a, "first LINE of the words".to_string(), vec![]),
                (c, "third LINE of the words".to_string(), vec![])
            ]
        );
        assert_eq!(planned.frozen_changed, 2, "both frozen lines had words typed over them");
        assert!(!planned.position_ignored && planned.surplus.is_none());

        // Then for real, through the apply, with a real session log to read back.
        let dir = std::env::temp_dir().join(format!("pagify-test-frozen-log-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        app.session_log = pagify_shell::session_log::SessionLog::start_in(dir.clone());
        let log_path = app.session_log.path().expect("the temp dir is writable").to_path_buf();
        let before = runs_by_object(&app);
        app.apply_one_edit(edit.clone());
        let after = runs_by_object(&app);

        assert_eq!(after[&b], before[&b], "the frozen line's own object was rewritten or hidden");
        assert_eq!(after[&d], before[&d], "the line nobody touched was rewritten");
        assert_eq!(after[&a].0.trim(), "first LINE of the words");
        assert_eq!(after[&c].0.trim(), "third LINE of the words");
        assert_eq!(after.len(), before.len(), "objects were added or lost");

        assert!(
            said(&app).contains("paragraph changed; 2 lines drawn as shapes were left as they are."),
            "the apply did not say what it left alone: {}",
            said(&app)
        );
        let logged = std::fs::read_to_string(&log_path).expect("the log file exists");
        assert!(
            logged.contains("paragraph diff:") && logged.contains("frozen lines [1, 2]"),
            "the frozen lines were not logged: {logged}"
        );
        // Which lines were retyped, removed and left alone — by index and by
        // count, and never by their words.
        assert!(
            logged.contains(
                "retyped lines [0, 3], removed lines [], 0 pieces taken off the page, frozen lines [1, 2]"
            ) && logged.contains("unchanged lines 1"),
            "the diff was not logged as retyped / removed / frozen / unchanged: {logged}"
        );
        for word in ["LINE", "TYPED", "fourth", "second", "words"] {
            let in_the_diff = logged.lines().filter(|l| l.contains("paragraph diff:")).any(|l| l.contains(word));
            assert!(!in_the_diff, "the diff line carries page text {word:?}: {logged}");
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **The first line of a block may itself be frozen with no text object**,
    /// and the whole buffer is then not trimmed: its empty first line is a line,
    /// and trimming it would pair every other line with the one before it.
    /// Built through [`PagifyApp::build_editor_from_lines`], applied through the
    /// real path.
    #[test]
    fn an_editor_built_with_an_empty_frozen_first_line_stays_aligned_through_an_apply() {
        let mut app = open_page("frozen-first", &FOUR[..3], "");
        let runs = app.tab().doc.as_ref().expect("open").session.text_runs(0).expect("runs");
        let face_names = app
            .tab()
            .doc
            .as_ref()
            .expect("open")
            .session
            .run_font_names(0)
            .unwrap_or_default();
        let above = Rect {
            left: runs[0].rect.left,
            top: runs[0].rect.top - 12.0,
            right: runs[0].rect.right,
            bottom: runs[0].rect.top,
        };
        let mut lines = vec![ParagraphLine { objects: Vec::new(), rect: above, frozen: true }];
        lines.extend(
            runs.iter().map(|r| ParagraphLine { objects: vec![r.object], rect: r.rect, frozen: false }),
        );
        let (edit, _look) = app
            .build_editor_from_lines(0, lines, &runs, &face_names, &std::collections::HashMap::new(), &[], None)
            .expect("a block with text in it");

        assert_eq!(edit.object, runs[0].object, "the editor sits on the first object of the first line that has one");
        // The frozen line with no text object of its own stands for the words
        // drawn as shapes: its placeholder, one entry like every other line.
        assert_eq!(
            edit.buffer,
            format!(
                "{}\nfirst line of the words\nsecond line of the words\nthird line of the words",
                block_input::OUTLINED_PLACEHOLDER
            )
        );
        assert_eq!(edit.frozen, [true, false, false, false]);
        assert!(edit.lines[0].0.is_empty());
        assert_eq!(edit.original.split('\n').count(), edit.lines.len());

        // Retype the last line only, through the real apply.
        let before = runs_by_object(&app);
        let retyped = edit.buffer.replace("third", "THIRD");
        app.tab_mut().editing_run = Some(edit);
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped;
        app.apply_editing_page();
        let after = runs_by_object(&app);
        assert_eq!(after[&0], before[&0], "the first text line was rewritten: the lines shifted");
        assert_eq!(after[&1], before[&1], "the second text line was rewritten: the lines shifted");
        assert_eq!(after[&2].0.trim(), "THIRD line of the words");
        assert_eq!(after.len(), before.len());
    }

    /// A block with nothing in it to edit — every line drawn as shapes — has no
    /// object to put an editor on, and says so.
    #[test]
    fn a_block_with_no_text_object_at_all_cannot_be_opened() {
        let mut app = open_page("all-frozen", &FOUR[..1], "");
        let runs = app.tab().doc.as_ref().expect("open").session.text_runs(0).expect("runs");
        let lines = vec![ParagraphLine { objects: Vec::new(), rect: runs[0].rect, frozen: true }];
        let refused = app
            .build_editor_from_lines(
                0,
                lines,
                &runs,
                &std::collections::HashMap::new(),
                &std::collections::HashMap::new(),
                &[],
                None,
            )
            .err()
            .expect("there is nothing to edit");
        assert!(refused.contains("drawn as shapes"), "{refused}");
    }

    /// **A paragraph that no longer lines up with its own text is refused in a
    /// release build too.** The check was a `debug_assert`; in release a line
    /// of text too few made the diff index past the end, or pair every later
    /// line with the wrong object.
    #[test]
    fn a_paragraph_that_no_longer_lines_up_is_refused_not_guessed_at() {
        let mut app = open_page("mismatch", &FOUR, "");
        pick_object(&mut app, 0);
        let good = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(good.lines.len(), 4, "setup: the four lines should be one paragraph");

        let mut too_few_lines_of_text = good.clone();
        too_few_lines_of_text.original = good.original.replacen('\n', " ", 1);
        let mut too_few_flags = good.clone();
        too_few_flags.frozen.pop();
        let mut no_lines = good.clone();
        no_lines.lines.clear();
        no_lines.frozen.clear();
        for (what, broken) in [
            ("one line of text too few", &too_few_lines_of_text),
            ("one frozen flag too few", &too_few_flags),
            ("no lines at all", &no_lines),
        ] {
            let refused = app
                .paragraph_edit_commands(broken, "a\nb\nc\nd")
                .err()
                .unwrap_or_else(|| panic!("{what} was not refused"));
            assert!(refused.contains("no longer lines up"), "{what}: {refused}");
        }

        // Through the apply: the page is untouched and the refusal is said.
        let before = runs_by_object(&app);
        let mut broken = too_few_lines_of_text;
        broken.buffer = good.buffer.replace("first", "FIRST");
        app.apply_one_edit(broken);
        assert_eq!(runs_by_object(&app), before, "a refused apply changed the page");
        assert!(said(&app).contains("no longer lines up"), "{}", said(&app));
    }

    /// **A block of one text object and a line drawn as shapes is a paragraph.**
    /// One object, two lines: counting objects alone sent it down the
    /// single-run path, which writes the buffer's later lines as *new* lines
    /// below the first — extra text the page never had.
    #[test]
    fn a_block_of_one_text_object_and_a_frozen_line_is_applied_as_a_paragraph() {
        let mut app = open_page("one-and-frozen", &[(100.0, 700.0, "one lonely line")], "");
        pick_object(&mut app, 0);
        let mut edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 1, "setup: a single run");
        let rect = edit.lines[0].1;
        edit.lines.push((Vec::new(), Rect { top: rect.bottom, bottom: rect.bottom + 12.0, ..rect }));
        edit.frozen = vec![false, true];
        edit.original = format!("{}\n", edit.original);
        edit.buffer = "one LONELY line\ntyped over the drawn line".to_string();

        let before = runs_by_object(&app);
        app.apply_one_edit(edit);
        let after = runs_by_object(&app);
        assert_eq!(after.len(), before.len(), "a new line was written below: {after:?}");
        assert_eq!(after[&0].0.trim(), "one LONELY line");
        assert!(
            said(&app).contains("1 line drawn as shapes was left as it is"),
            "the apply did not say what it left alone: {}",
            said(&app)
        );
    }

    /// **A lone frozen line with one text piece is never rewritten either.**
    /// One line, one object: nothing but the frozen flag sends it down the
    /// paragraph path, which leaves it as it is.
    #[test]
    fn a_lone_frozen_line_is_never_rewritten() {
        let mut app = open_page("lone-frozen", &[(100.0, 700.0, "one lonely line")], "");
        pick_object(&mut app, 0);
        let mut edit = app.tab().editing_run.as_ref().expect("picked").clone();
        edit.frozen = vec![true];
        edit.buffer = "one LONELY line".to_string();

        let before = runs_by_object(&app);
        app.apply_one_edit(edit);
        assert_eq!(runs_by_object(&app), before, "a frozen line was rewritten");
        assert!(
            said(&app).contains("unchanged; 1 line drawn as shapes was left as it is."),
            "the apply did not say what it left alone: {}",
            said(&app)
        );
    }

    /// Every way of picking gives one frozen flag per line, none of them set.
    #[test]
    fn every_way_of_picking_gives_one_frozen_flag_per_line_and_none_set() {
        let mut app = open_page("flags-single", &[(100.0, 700.0, "one lonely line")], "");
        pick_object(&mut app, 0);
        let single = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!((single.lines.len(), single.frozen), (1, vec![false]));

        let mut app = open_page("flags-paragraph", &FOUR, "");
        pick_object(&mut app, 0);
        let paragraph = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(paragraph.lines.len(), 4);
        assert_eq!(paragraph.frozen, vec![false; 4]);
    }

    /// Every way of picking stamps the document's command-history generation.
    #[test]
    fn every_way_of_picking_stamps_the_documents_generation() {
        let mut app = open_page("stamp-single", &[(100.0, 700.0, "one lonely line")], "");
        pick_object(&mut app, 0);
        let single = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(single.doc_generation, app.doc_generation());

        // After the history has moved, a fresh pick carries the new number.
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = "one LONELY line".to_string();
        app.apply_editing_page();
        assert_ne!(app.doc_generation(), single.doc_generation, "setup: an apply moves the generation");
        let mut app2 = open_page("stamp-paragraph", &FOUR, "");
        pick_object(&mut app2, 0);
        let paragraph = app2.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(paragraph.lines.len(), 4, "setup: a paragraph, built by `build_editor_from_lines`");
        assert_eq!(paragraph.doc_generation, app2.doc_generation());
        pick_object(&mut app, 0);
        assert_eq!(
            app.tab().editing_run.as_ref().expect("picked again").doc_generation,
            app.doc_generation(),
            "a fresh pick must carry the generation as it is now"
        );
    }

    /// **An edit picked before an undo is refused, not written onto objects
    /// that may have been renumbered.** The editor holds page-object numbers; an
    /// edit, an undo or a redo between the pick and the apply can renumber them.
    #[test]
    fn an_edit_picked_before_an_undo_is_refused_rather_than_written_onto_other_objects() {
        let mut app = open_page("stale-undo", &FOUR, "");
        // Some history to undo: retype the first line. This also shows a fresh
        // pick still applies.
        pick_object(&mut app, 0);
        let retyped = app.tab().editing_run.as_ref().expect("picked").buffer.replace("first", "FIRST");
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped;
        app.apply_editing_page();
        assert!(runs_by_object(&app)[&0].0.contains("FIRST"), "setup: the first edit applied");

        // Pick again, then move the document under the open editor.
        pick_object(&mut app, 0);
        let picked_at = app.tab().editing_run.as_ref().expect("picked").doc_generation;
        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone, "setup: there was something to undo");
        assert_ne!(app.doc_generation(), picked_at, "setup: the undo moved the generation");
        let after_undo = runs_by_object(&app);

        let typed = app.tab().editing_run.as_ref().expect("still open").buffer.replace("second", "SECOND");
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed;
        app.apply_editing_page();
        assert_eq!(runs_by_object(&app), after_undo, "an edit picked before the undo was written");
        assert!(said(&app).contains(STALE_EDITOR_MESSAGE), "{}", said(&app));
        assert!(app.tab().editing_run.is_none(), "the editor should be closed");
    }

    /// A stale editor with nothing typed in it just closes, as any other does.
    #[test]
    fn a_stale_edit_with_nothing_typed_just_closes() {
        let mut app = open_page("stale-nothing", &FOUR, "");
        pick_object(&mut app, 0);
        let retyped = app.tab().editing_run.as_ref().expect("picked").buffer.replace("first", "FIRST");
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped;
        app.apply_editing_page();

        pick_object(&mut app, 0);
        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone, "setup: there was something to undo");
        let after_undo = runs_by_object(&app);
        app.apply_editing_page();
        assert_eq!(runs_by_object(&app), after_undo);
        assert!(app.tab().editing_run.is_none());
        assert!(!said(&app).contains("not applied"), "a no-op was refused as if it were a write: {}", said(&app));
    }

    /// **On the real file: retyping a line made of several pieces replaces
    /// those pieces and writes nothing else.** The CAMINO paragraph's first line
    /// is three pieces ("The COB in", "HSI ", "products sup"); retyped, it is its
    /// first piece holding the new words, the other two come off the page, and
    /// every other object on the page is exactly as it was. (Every apply used to
    /// collapse all of the paragraph's lines, then to paint the other pieces in the
    /// page's colour.) Skipped, with a note, where the file is not on this machine.
    #[test]
    fn retyping_a_multi_piece_line_of_the_real_paragraph_replaces_its_pieces_and_writes_nothing_else() {
        let path = r"C:\Users\hsili\Downloads\CAMINO elitee-plus 3.0.pdf";
        let mut app = PagifyApp::new(Some(path));
        if app.tab().doc.is_none() {
            eprintln!("skipping: CAMINO not present on this machine");
            return;
        }
        let seed = app
            .tab()
            .doc
            .as_ref()
            .expect("open")
            .session
            .text_runs(0)
            .expect("runs")
            .into_iter()
            .find(|r| r.text.contains("manufacturers"))
            .expect("the COB paragraph's own run was not found — has the file changed?");
        app.submit("edittext");
        app.pick_text_run(
            0,
            AppPoint {
                x: ((seed.rect.left + seed.rect.right) / 2.0) as f64,
                y: ((seed.rect.top + seed.rect.bottom) / 2.0) as f64,
            },
        )
        .expect("picked");
        let edit = app.tab().editing_run.as_ref().expect("picked").clone();
        let lines_text: Vec<String> = edit.buffer.split('\n').map(str::to_string).collect();
        assert!(edit.lines.len() >= 4, "setup: need a first, a middle and a last line");
        assert!(
            edit.lines.iter().any(|(objects, _)| objects.len() > 1),
            "setup: the paragraph has a line made of several pieces, or nothing here could show a collapse"
        );

        // A middle line made of plain words only — no control code — retyped by
        // repeating a word it already uses, so no new letter is needed. Made of
        // several pieces, so that taking the others off the page is something the
        // apply has to do (and this test can see it done).
        //
        // **A line may end in the hyphen where the page breaks a word**: the thin
        // hyphen glyphs are members of their lines now (they used to be left out of
        // the buffer), and every multi-piece line of this paragraph ends in one. The
        // retyped line drops it — a hyphen written comes back from PDFium as a
        // control code, which would make the words differ for a reason that is not
        // what is under test — and keeps the plain words before it.
        let plain = |text: &str| {
            text.trim_end().trim_end_matches('-').chars().all(|c| c.is_alphabetic() || c == ' ' || c == '.' || c == ',')
        };
        let target = (0..lines_text.len() - 1)
            .find(|&i| edit.lines[i].0.len() > 1 && plain(&lines_text[i]))
            .expect("a line of plain words made of several pieces");
        let word = lines_text[target]
            .split_whitespace()
            .find(|w| w.chars().count() > 2 && w.chars().all(char::is_alphabetic))
            .expect("a plain word");
        let mut retyped = lines_text.clone();
        retyped[target] = format!("{} {word}", lines_text[target].trim_end().trim_end_matches('-'));

        let before = runs_in_order(&app);
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped.join("\n");
        app.apply_editing_page();
        let after = runs_in_order(&app);

        // The retyped line is its first piece with the new words; its other
        // pieces are gone from the page; every other object — every piece of
        // every other line — is exactly as it was.
        let (first, rest) = edit.lines[target].0.split_first().expect("the line has objects");
        assert_page_after(
            "one middle line of the CAMINO paragraph",
            &before,
            &after,
            &[(*first, &retyped[target])],
            rest,
        );
    }

    // -- replacing pieces: what the page looks like, and undo ----------------

    /// **ONE undo puts the page back EXACTLY, and redo does it again.** Not
    /// "the same words": every run's words, colour, box, origin and size, and the
    /// picture itself pixel for pixel. Re-typing the old words (what undo used to
    /// do) loses the kerning of a `TJ` and the producer's own spacing; the
    /// replace undoes by a snapshot of the page instead.
    #[test]
    fn undo_of_an_apply_puts_the_page_back_exactly_and_redo_does_it_again() {
        let (mut app, before, _edit, _new_third) = five_lines_with_a_word_retyped("undo-exact");
        let picture_before = picture(&app);
        app.apply_editing_page();
        let applied = runs_in_order(&app);
        let picture_applied = picture(&app);
        assert!(
            !same_picture(&picture_before, &picture_applied),
            "setup: the edit changed nothing that is drawn"
        );
        assert_eq!(applied.len(), before.len() - 1, "setup: one piece came off the page");

        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone, "the apply did not undo in one step");
        let restored = runs_in_order(&app);
        assert_eq!(restored.len(), before.len(), "undo did not bring the removed piece back");
        for (was, now) in before.iter().zip(&restored) {
            assert_eq!(was.object, now.object, "undo renumbered the page");
            assert!(same_run(was, now), "undo did not restore a run exactly: {was:?} now {now:?}");
        }
        assert!(same_picture(&picture(&app), &picture_before), "the page is not pixel-identical after undo");

        let (redone, _) = app.tab().doc.as_ref().expect("open").session.redo().expect("redo");
        assert!(redone, "nothing to redo");
        let again = runs_in_order(&app);
        assert_eq!(again.len(), applied.len());
        for (was, now) in applied.iter().zip(&again) {
            assert!(same_run(was, now), "redo did not reapply exactly: {was:?} now {now:?}");
        }
        assert!(same_picture(&picture(&app), &picture_applied), "the page is not pixel-identical after redo");
    }

    /// **A later pick of the edited paragraph shows exactly the edited lines.**
    /// With the old pieces painted over instead of removed, the detector found
    /// them again and the buffer read each retyped line's old words a second
    /// time.
    #[test]
    fn a_later_pick_of_the_edited_paragraph_shows_exactly_the_edited_lines() {
        let (mut app, _before, edit, _new_third) = five_lines_with_a_word_retyped("re-pick");
        let expected: Vec<String> = edit.buffer.replace("labore", "LABORE").split('\n').map(squeeze).collect();
        app.apply_editing_page();

        app.tab_mut().editing_run = None;
        pick_object(&mut app, 0);
        let again = app.tab().editing_run.as_ref().expect("picked again").clone();
        let lines: Vec<String> = again.buffer.split('\n').map(squeeze).collect();
        assert_eq!(lines, expected, "a later pick does not read the page's own lines");
        assert_eq!(again.lines.len(), 5);
        assert_eq!(
            again.lines.iter().map(|(objects, _)| objects.len()).collect::<Vec<_>>(),
            [2, 2, 1, 2, 2],
            "the retyped line is one piece now and the others are as they were"
        );
        assert_eq!(again.buffer.matches("dolore").count(), 1, "a word of the retyped line is there twice");
    }

    /// **A first piece that becomes LONGER than the old one is not painted over
    /// by the line's other piece.** The old piece sat after the first by its own
    /// `Td`, painted in the page's colour *after* the new words; under a longer
    /// first piece it erased part of them (23% of one datasheet line's ink).
    /// Compared against a page on which the same words are simply written in one
    /// piece: the two pictures must be identical.
    #[test]
    fn a_longer_first_piece_is_not_painted_over_by_the_pieces_that_were_after_it() {
        const SECOND: (&str, &str) = ("sit amet ", "consectetur elit");
        let long = "Lorem ipsum dolor sit amet consectetur adipiscing elit sed do";
        let mut app = two_piece_page("overpaint", &[("Lorem ", "ipsum dolor"), SECOND]);
        pick_object(&mut app, 0);
        let edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 2, "setup: two lines: {:?}", edit.buffer);
        let first_line_old = edit.buffer.split('\n').next().expect("a first line").to_string();
        assert!(squeeze(&first_line_old).len() < long.len(), "setup: the new line is longer");
        let typed = edit.buffer.replacen(&first_line_old, long, 1);
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed;
        app.apply_editing_page();

        // The same words, one piece, same place; the second row as it was.
        let reference = two_piece_page("overpaint-reference", &[(long, ""), SECOND]);
        assert!(
            same_picture(&picture(&app), &picture(&reference)),
            "the retyped line is not drawn as the same words written in one piece would be — \
             a piece left on the page paints over part of it, or the words are not where they were"
        );
    }

    /// A line the person deleted comes off the page whole: every one of its
    /// pieces, and nothing else.
    #[test]
    fn deleting_a_line_removes_every_one_of_its_pieces() {
        let mut app = two_piece_page("delete-line", &ROWS);
        pick_object(&mut app, 4);
        let edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 5, "setup: five lines");
        let before = runs_in_order(&app);
        let mut lines: Vec<&str> = edit.buffer.split('\n').collect();
        lines.remove(2);
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = lines.join("\n");
        app.apply_editing_page();
        let after = runs_in_order(&app);
        assert_page_after("a deleted line", &before, &after, &[], &edit.lines[2].0);

        // And it comes back, exactly, with one undo.
        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone);
        let restored = runs_in_order(&app);
        assert_eq!(restored.len(), before.len());
        assert!(before.iter().zip(&restored).all(|(a, b)| same_run(a, b)), "undo did not restore the deleted line");
    }

    /// **A new colour for the paragraph reaches every piece that stays**, and
    /// it undoes together with the replace in ONE step — the colour is written
    /// first, while the object numbers are still good, and undone last.
    #[test]
    fn a_new_colour_reaches_every_piece_that_stays_and_undoes_with_the_replace_in_one_step() {
        let red = Color { r: 200, g: 0, b: 0, a: 255 };
        let (mut app, before, edit, new_third) = five_lines_with_a_word_retyped("recolour");
        assert!(before.iter().all(|r| r.color != red), "setup: nothing is red yet");
        app.tab_mut().editing_run.as_mut().expect("editing").style.color = Some(red);
        let picture_before = picture(&app);
        app.apply_editing_page();
        let after = runs_in_order(&app);

        // The page lost the one piece; every run that is left is red, and the
        // retyped one holds the new words.
        let (first, second) = (edit.lines[2].0[0], edit.lines[2].0[1]);
        let recoloured: Vec<TextRun> =
            before.iter().map(|r| TextRun { color: red, ..r.clone() }).collect();
        assert_page_after("a new colour and a retyped line", &recoloured, &after, &[(first, &new_third)], &[second]);
        assert!(after.iter().all(|r| r.color == red), "a piece that stays was not recoloured: {after:?}");

        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone, "the colour and the replace did not undo as one step");
        let restored = runs_in_order(&app);
        assert_eq!(restored.len(), before.len());
        assert!(before.iter().zip(&restored).all(|(a, b)| same_run(a, b)), "undo left a colour or a piece behind");
        assert!(same_picture(&picture(&app), &picture_before), "not pixel-identical after one undo");
    }

    /// A colour with no word changed is just the colour: every piece of every
    /// line, no piece removed.
    #[test]
    fn a_new_colour_alone_recolours_the_whole_paragraph_and_removes_nothing() {
        let red = Color { r: 200, g: 0, b: 0, a: 255 };
        let mut app = two_piece_page("recolour-only", &ROWS);
        pick_object(&mut app, 4);
        let before = runs_in_order(&app);
        app.tab_mut().editing_run.as_mut().expect("editing").style.color = Some(red);
        app.apply_editing_page();
        let after = runs_in_order(&app);
        let recoloured: Vec<TextRun> = before.iter().map(|r| TextRun { color: red, ..r.clone() }).collect();
        assert_page_after("a colour and nothing else", &recoloured, &after, &[], &[]);
        assert!(said(&app).contains("paragraph changed"), "{}", said(&app));
    }

    /// **A position asked for is said, never silently dropped**: the panel
    /// offers one for a paragraph, a paragraph has no single place to move to,
    /// and the retyped line stays where it was.
    #[test]
    fn a_position_asked_for_is_said_not_silently_dropped() {
        let (mut app, before, edit, new_third) = five_lines_with_a_word_retyped("position");
        app.tab_mut().editing_run.as_mut().expect("editing").style.at = Some((300.0, 300.0));
        app.apply_editing_page();
        let (first, second) = (edit.lines[2].0[0], edit.lines[2].0[1]);
        assert_page_after("a position asked for", &before, &runs_in_order(&app), &[(first, &new_third)], &[second]);
        assert!(
            said(&app).contains("paragraph changed; the position was not changed"),
            "the apply did not say the position was not applied: {}",
            said(&app)
        );
    }

    /// **An engine refusal leaves the page exactly as it was, and is said.** The
    /// replace is atomic: here a line is made to name an object that is not text
    /// at all, which the engine refuses, and not one thing changes — **not even
    /// the new line typed below the paragraph**, which is written only once the
    /// replace has gone through.
    #[test]
    fn an_engine_refusal_leaves_the_page_as_it_was_and_is_said() {
        let mut app = open_page("refusal", &FOUR, "0 0 50 50 re f\n");
        pick_object(&mut app, 0);
        let mut edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 4, "setup: four lines");
        // The fifth object is the rectangle.
        edit.lines[1].0 = vec![4];
        edit.buffer = format!("{}\nan extra line", edit.buffer.replacen("second", "SECOND", 1));
        let (runs_before, picture_before) = (runs_in_order(&app), picture(&app));
        let typed = edit.buffer.clone();
        app.tab_mut().editing_run = Some(edit);
        assert!(app.apply_editing_page(), "the refusal was not reported as one");
        assert_eq!(runs_in_order(&app).len(), runs_before.len());
        assert!(runs_in_order(&app).iter().zip(&runs_before).all(|(a, b)| same_run(a, b)), "the page changed");
        assert!(same_picture(&picture(&app), &picture_before), "the page's picture changed");
        let last = app.cmd.history().last().expect("something was said").clone();
        assert!(matches!(last.kind, Kind::Error), "the refusal was not said as an error: {last:?}");
        assert!(
            last.text.ends_with(" — nothing was changed."),
            "the refusal did not say that nothing was changed: {last:?}"
        );
        // **Changed with the reason**: the editor used to be closed here, with the
        // person's typing thrown away with the refusal. It stays now, with the words
        // in it and the refusal remembered (shown beside Apply).
        let kept = app.tab().editing_run.as_ref().expect("a refused edit keeps its editor");
        assert_eq!(kept.buffer, typed, "the typing was not kept");
        assert_eq!(kept.refusal.as_ref().map(|r| r.reason.as_str()), Some(last.text.as_str()));
    }

    /// **A refusal after the colour has been written puts the colour back too.**
    /// The colour and the replace are one batch, and a batch is all or nothing:
    /// the replace is refused (a line made to name an object that is not text), and
    /// the colour that went first must not be left on the page.
    #[test]
    fn a_refusal_after_a_new_colour_leaves_the_page_exactly_as_it_was() {
        let red = Color { r: 200, g: 0, b: 0, a: 255 };
        let mut app = open_page("refusal-colour", &FOUR, "0 0 50 50 re f\n");
        pick_object(&mut app, 0);
        let mut edit = app.tab().editing_run.as_ref().expect("picked").clone();
        edit.lines[1].0 = vec![1, 4]; // the line's own piece, and the rectangle as a second "piece": not text
        edit.buffer = edit.buffer.replacen("second", "SECOND", 1);
        edit.style.color = Some(red);
        let (runs_before, picture_before) = (runs_in_order(&app), picture(&app));
        app.tab_mut().editing_run = Some(edit);
        app.apply_editing_page();
        let last = app.cmd.history().last().expect("something was said").clone();
        assert!(matches!(last.kind, Kind::Error), "the refusal was not said as an error: {last:?}");
        let runs_after = runs_in_order(&app);
        assert_eq!(runs_after.len(), runs_before.len());
        assert!(
            runs_before.iter().zip(&runs_after).all(|(a, b)| same_run(a, b)),
            "the colour was left on the page after the refusal: {runs_after:?}"
        );
        assert!(same_picture(&picture(&app), &picture_before), "the page's picture changed");
    }

    /// **New lines typed past the paragraph's end are written below it, after
    /// the replace** — by position, since the replace renumbers the page — and
    /// the whole thing still undoes exactly (the new line first, then the replace).
    #[test]
    fn new_lines_typed_past_the_end_are_written_below_the_paragraph_after_the_replace() {
        let (mut app, before, edit, new_third) = five_lines_with_a_word_retyped("surplus");
        let typed = format!("{}\na brand new last line", app.tab().editing_run.as_ref().unwrap().buffer);
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed;
        app.apply_editing_page();
        let after = runs_in_order(&app);
        let (first, second) = (edit.lines[2].0[0], edit.lines[2].0[1]);

        // The page as it was, minus the one piece, is the first `before.len() - 1`
        // objects; what follows is the new line, which a text mark writes as one
        // object per letter, left to right on one baseline.
        let kept = before.len() - 1;
        assert!(after.len() > kept, "the new line is not on the page: {after:?}");
        assert_page_after("the rest of the page", &before, &after[..kept], &[(first, &new_third)], &[second]);
        let mut letters: Vec<&TextRun> = after[kept..].iter().collect();
        letters.sort_by(|a, b| a.rect.left.total_cmp(&b.rect.left));
        let written: String = letters.iter().map(|r| r.text.trim()).collect();
        assert_eq!(written, "abrandnewlastline", "the new line's letters: {letters:?}");
        let last_row_bottom = before.iter().map(|r| r.rect.bottom).fold(f32::MIN, f32::max);
        assert!(
            letters.iter().all(|r| r.rect.top >= last_row_bottom - 1.0),
            "the new line is not below the paragraph (its last row ends at {last_row_bottom}): {letters:?}"
        );

        // Undo takes the new line off first, then restores the page.
        for step in ["the new line", "the replace"] {
            let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
            assert!(undone, "{step} did not undo");
        }
        let restored = runs_in_order(&app);
        assert_eq!(restored.len(), before.len());
        assert!(before.iter().zip(&restored).all(|(a, b)| same_run(a, b)), "two undos did not restore the page");
    }

    /// **A join names objects by number, and a replace renumbers them**: pieces
    /// that came off move every later object down, so a join left alone would
    /// name other objects and open the wrong paragraph. Forgotten when pieces
    /// came off the page; kept when nothing did.
    #[test]
    fn a_join_is_forgotten_when_pieces_came_off_the_page_and_kept_when_none_did() {
        let (mut app, ..) = five_lines_with_a_word_retyped("join-forgotten");
        assert!(app.declare_group(0, vec![0, 2, 4]), "setup: the join is declared");
        app.apply_editing_page();
        assert!(app.tab().joined_groups.is_empty(), "a join survived the renumbering: {:?}", app.tab().joined_groups);

        // One piece a line, so nothing comes off and nothing is renumbered.
        let mut app = open_page("join-kept", &FOUR, "");
        pick_object(&mut app, 0);
        assert!(app.declare_group(0, vec![0, 1, 2, 3]), "setup: the join is declared");
        let retyped = app.tab().editing_run.as_ref().expect("picked").buffer.replace("second", "SECOND");
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped;
        app.apply_editing_page();
        let kept: Vec<(usize, Vec<usize>)> =
            app.tab().joined_groups.iter().map(|group| (group.page, group.objects.clone())).collect();
        assert_eq!(kept, [(0, vec![0, 1, 2, 3])], "a join was forgotten for no reason");
    }

    /// **A font picked for a paragraph is written on every line, in one step.** The
    /// engine refuses a batch in which two lines each need a new font embedded; a
    /// font picked for the whole block is one font for all of them.
    #[test]
    fn a_font_picked_for_a_paragraph_is_written_on_every_line_in_one_step() {
        let mut app = open_page("font-all-lines", &FOUR, "");
        let picked = app
            .writing_faces()
            .into_iter()
            .find(|n| n.to_ascii_lowercase().contains("montserrat"))
            .expect("Montserrat is bundled");
        pick_object(&mut app, 0);
        let before = runs_in_order(&app);
        let picture_before = picture(&app);
        app.tab_mut().editing_run.as_mut().expect("editing").style.face = Some(picked.clone());
        app.apply_editing_page();
        assert!(said(&app).contains("paragraph changed"), "the font pick was refused: {}", said(&app));
        let after = runs_in_order(&app);
        assert_eq!(after.len(), before.len());
        assert!(
            before.iter().zip(&after).all(|(a, b)| squeeze(&a.text) == squeeze(&b.text)),
            "a line's words changed with the font: {after:?}"
        );
        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone, "the font pick did not undo");
        assert!(same_picture(&picture(&app), &picture_before), "one undo did not restore the page");
    }

    /// **A new colour for a real paragraph changes the colour and nothing else.**
    /// The datasheet's 13-line paragraph and CAMINO's COB paragraph have lines of
    /// three to eight pieces, several ending in a hyphen glyph that the extracted
    /// text leaves out, and the datasheet's has two lines with a word the page
    /// draws as shapes (left as they are, so not recoloured). A colour edit that
    /// sent a piece's words back without its hyphen would drop it; every other
    /// run — words, box, origin, size — must read exactly as it did, and one
    /// undo restores the picture. Skipped where a file is not on this machine.
    #[test]
    fn a_new_colour_for_a_real_paragraph_changes_the_colour_and_nothing_else() {
        let _turn = tests_support::one_at_a_time();
        let red = Color { r: 200, g: 0, b: 0, a: 255 };
        let mut any = false;
        for (path, seed) in [
            (r"C:\Users\hsili\Desktop\Datasheets - Editors market - Marina mall.pdf", None),
            (r"C:\Users\hsili\Downloads\CAMINO elitee-plus 3.0.pdf", Some("manufacturers")),
        ] {
            if !std::path::Path::new(path).is_file() {
                eprintln!("skipping: {path} is not on this machine");
                continue;
            }
            any = true;
            let mut app = PagifyApp::new(Some(path));
            let before = runs_in_order(&app);
            let seed = match seed {
                Some(text) => before.iter().find(|r| r.text.contains(text)),
                None => before.iter().find(|r| r.object == 986),
            }
            .expect("the paragraph's own run was not found — has the file changed?");
            app.submit("edittext");
            app.pick_text_run(
                0,
                AppPoint {
                    x: ((seed.rect.left + seed.rect.right) / 2.0) as f64,
                    y: ((seed.rect.top + seed.rect.bottom) / 2.0) as f64,
                },
            )
            .expect("picked");
            let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
            assert!(edit.lines.len() >= 5, "setup: {path}: a real paragraph");
            let picture_before = picture(&app);
            app.tab_mut().editing_run.as_mut().expect("editing").style.color = Some(red);
            app.apply_editing_page();
            assert!(said(&app).contains("paragraph changed"), "{path}: the colour was refused: {}", said(&app));

            // Every piece of every line that is not drawn as shapes is red, and
            // nothing else changed; no object came off the page.
            let in_a_frozen_line = |object: usize| {
                edit.lines.iter().zip(&edit.frozen).any(|((objects, _), frozen)| *frozen && objects.contains(&object))
            };
            let in_a_line = |object: usize| edit.lines.iter().any(|(objects, _)| objects.contains(&object));
            let expected: Vec<TextRun> = before
                .iter()
                .map(|r| {
                    if in_a_line(r.object) && !in_a_frozen_line(r.object) {
                        TextRun { color: red, ..r.clone() }
                    } else {
                        r.clone()
                    }
                })
                .collect();
            let after = runs_in_order(&app);
            tests_support::assert_page_after(&format!("{path}: a new colour"), &expected, &after, &[], &[]);
            assert!(!same_picture(&picture(&app), &picture_before), "{path}: the colour changed nothing that is drawn");

            let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
            assert!(undone, "{path}: the colour did not undo");
            assert!(same_picture(&picture(&app), &picture_before), "{path}: one undo did not restore the page");
        }
        assert!(any, "neither real file is on this machine");
    }

    /// **A size set for a paragraph reaches every line** — every piece of every
    /// line, which is what a size change has to rewrite — and undoes in one step.
    #[test]
    fn a_size_set_for_a_paragraph_reaches_every_line_and_undoes_in_one_step() {
        let mut app = two_piece_page("size-all-lines", &ROWS);
        pick_object(&mut app, 4);
        let before = runs_in_order(&app);
        let picture_before = picture(&app);
        app.tab_mut().editing_run.as_mut().expect("editing").style.size = Some(14.0);
        app.apply_editing_page();
        assert!(said(&app).contains("paragraph changed"), "the size was refused: {}", said(&app));
        let after = runs_in_order(&app);
        assert_eq!(after.len(), ROWS.len(), "every line is its first piece now, one object each");
        assert!(after.iter().all(|r| (r.size - 14.0).abs() < 0.05), "a line was left at the old size: {after:?}");
        let (undone, _) = app.tab().doc.as_ref().expect("open").session.undo().expect("undo");
        assert!(undone, "the size change did not undo");
        let restored = runs_in_order(&app);
        assert!(before.iter().zip(&restored).all(|(a, b)| same_run(a, b)), "undo did not restore the lines");
        assert!(same_picture(&picture(&app), &picture_before), "one undo did not restore the page");
    }

    // -- a retyped line keeps the width it had (justification) ---------------
    //
    // The app asks the engine to keep a retyped line of a justified paragraph as
    // wide as it was (`TextLineEdit::Retype`'s `justify_to`, see
    // `paragraph_lines::STRETCH_JUSTIFIED_LINES`). The engine honours the field —
    // the left edge stays, the width is the right edge minus the left of the
    // original line's box, exact to a thousandth of a point — so the switch is on
    // and the first two tests below, the ones that need it, run. (They were ignored
    // while the engine refused any width; they failed exactly as the report said:
    // "9.51 pt short", "a click opened 2 of the paragraph's 13 lines".)

    /// A real justified paragraph opened for editing: the datasheet's 13-line
    /// paragraph (click on object 986 of page 1) or CAMINO's COB paragraph (the
    /// run that says "manufacturers"). `None` where the file is not on this
    /// machine.
    fn open_a_justified_paragraph(path: &str, seed_text: Option<&str>) -> Option<(PagifyApp, EditingRun)> {
        if !std::path::Path::new(path).is_file() {
            eprintln!("skipping: {path} is not on this machine");
            return None;
        }
        let mut app = PagifyApp::new(Some(path));
        let runs = runs_in_order(&app);
        let run = match seed_text {
            Some(text) => runs.iter().find(|r| r.text.contains(text)),
            None => runs.iter().find(|r| r.object == 986),
        }
        .expect("the paragraph's own run was not found — has the file changed?");
        app.submit("edittext");
        app.pick_text_run(
            0,
            AppPoint {
                x: ((run.rect.left + run.rect.right) / 2.0) as f64,
                y: ((run.rect.top + run.rect.bottom) / 2.0) as f64,
            },
        )
        .expect("picked");
        let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
        assert_eq!(edit.lines.len(), 13, "setup: the 13-line justified paragraph");
        assert!(paragraph_lines::ends_at_one_margin(&edit.lines), "setup: its lines end at one margin");
        Some((app, edit))
    }

    const MARINA_PARAGRAPH: (&str, Option<&str>) =
        (r"C:\Users\hsili\Desktop\Datasheets - Editors market - Marina mall.pdf", None);
    const CAMINO_PARAGRAPH: (&str, Option<&str>) =
        (r"C:\Users\hsili\Downloads\CAMINO elitee-plus 3.0.pdf", Some("manufacturers"));

    /// A plain middle line of the paragraph — words only, at least three — and
    /// the buffer with that line's second word dropped: the line comes out
    /// narrower than it was, and every letter it needs is on the page already.
    fn drop_a_word_from_a_middle_line(edit: &EditingRun) -> (usize, String) {
        let lines: Vec<&str> = edit.buffer.split('\n').collect();
        let target = (1..lines.len() - 1)
            .find(|&i| {
                !edit.frozen[i]
                    && lines[i].split_whitespace().count() >= 3
                    && lines[i].chars().all(|c| c.is_alphabetic() || c == ' ')
            })
            .expect("a plain middle line of at least three words");
        let mut words: Vec<&str> = lines[target].split_whitespace().collect();
        words.remove(1);
        let mut retyped: Vec<String> = lines.iter().map(|l| l.to_string()).collect();
        retyped[target] = words.join(" ");
        (target, retyped.join("\n"))
    }

    /// Where a line's first piece is after the pieces `removed` came off the
    /// page: its object number, less one for every removed piece numbered below it.
    fn renumbered(first: usize, removed: &[usize]) -> usize {
        first - removed.iter().filter(|object| **object < first).count()
    }

    /// **A retyped line of a justified paragraph ends where it ended** — within
    /// half a point — instead of a few points short of the margin. The retype
    /// writes plain words and loses the producer's inter-word spacing; asked for
    /// the width the line had, the engine stretches the spaces back.
    #[test]
    fn a_retyped_line_of_a_justified_paragraph_ends_where_it_ended() {
        let _turn = tests_support::one_at_a_time();
        let mut any = false;
        for (path, seed) in [MARINA_PARAGRAPH, CAMINO_PARAGRAPH] {
            let Some((mut app, edit)) = open_a_justified_paragraph(path, seed) else { continue };
            any = true;
            let (target, retyped) = drop_a_word_from_a_middle_line(&edit);
            let original = edit.lines[target].1;
            let (first, rest) = edit.lines[target].0.split_first().expect("the line has objects");
            app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped;
            app.apply_editing_page();
            let after = runs_in_order(&app);
            let now = after
                .iter()
                .find(|r| r.object == renumbered(*first, rest))
                .unwrap_or_else(|| panic!("{path}: the retyped line's first piece was not found"));
            assert!(
                (now.rect.right - original.right).abs() <= 0.5,
                "{path}: line {target} ends at {:.2}; it ended at {:.2} ({:.2} pt short)",
                now.rect.right,
                original.right,
                original.right - now.rect.right
            );
            assert!(
                (now.rect.left - original.left).abs() <= 0.5,
                "{path}: line {target} moved sideways: {:.2} then {:.2}",
                original.left,
                now.rect.left
            );
        }
        assert!(any, "neither real file is on this machine");
    }

    /// **After editing a line of a justified paragraph a click on it opens the
    /// WHOLE paragraph again.** The retyped line used to end short; the detector
    /// reads a short line as the paragraph's last and stopped there, so the next
    /// click opened only the lines above it (CAMINO: 4 of 13).
    #[test]
    fn after_editing_one_line_a_click_opens_every_line_of_the_paragraph_again() {
        let _turn = tests_support::one_at_a_time();
        let mut any = false;
        for (path, seed) in [MARINA_PARAGRAPH, CAMINO_PARAGRAPH] {
            let Some((mut app, edit)) = open_a_justified_paragraph(path, seed) else { continue };
            any = true;
            let (target, retyped) = drop_a_word_from_a_middle_line(&edit);
            let (first, rest) = edit.lines[target].0.split_first().expect("the line has objects");
            app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped.clone();
            app.apply_editing_page();

            // Click the retyped line itself, and a line below it.
            let after = runs_in_order(&app);
            for (what, object) in [
                ("the retyped line", renumbered(*first, rest)),
                ("the line after it", renumbered(edit.lines[target + 1].0[0], rest)),
            ] {
                app.tab_mut().editing_run = None;
                let run = after.iter().find(|r| r.object == object).expect("a piece");
                app.pick_text_run(
                    0,
                    AppPoint {
                        x: ((run.rect.left + run.rect.right) / 2.0) as f64,
                        y: ((run.rect.top + run.rect.bottom) / 2.0) as f64,
                    },
                )
                .expect("picked again");
                let again = app.tab().editing_run.as_ref().expect("an editor opened").clone();
                assert_eq!(
                    again.lines.len(),
                    edit.lines.len(),
                    "{path}: a click on {what} opened {} of the paragraph's {} lines",
                    again.lines.len(),
                    edit.lines.len()
                );
                assert_eq!(
                    again.buffer.split('\n').map(squeeze).collect::<Vec<_>>(),
                    retyped.split('\n').map(squeeze).collect::<Vec<_>>(),
                    "{path}: a click on {what} does not read the paragraph as it was edited"
                );
            }
        }
        assert!(any, "neither real file is on this machine");
    }

    /// **The paragraph's last line is not stretched**: a short closing line stays
    /// as short as its words make it, and nothing else on the page changes.
    #[test]
    fn the_last_line_of_a_justified_paragraph_is_not_stretched() {
        let _turn = tests_support::one_at_a_time();
        let mut any = false;
        for (path, seed) in [MARINA_PARAGRAPH, CAMINO_PARAGRAPH] {
            let Some((mut app, edit)) = open_a_justified_paragraph(path, seed) else { continue };
            any = true;
            let last = edit.lines.len() - 1;
            let mut lines: Vec<String> = edit.buffer.split('\n').map(str::to_string).collect();
            // The last line cut to its first two thirds, a letter at a time — a
            // short closing line may be a single word — so it is narrower and
            // needs no letter the page does not already have.
            let cut = (lines[last].chars().count() * 2 / 3).max(1);
            lines[last] = lines[last].chars().take(cut).collect();
            let original = edit.lines[last].1;
            let (first, rest) = edit.lines[last].0.split_first().expect("the line has objects");
            let before = runs_in_order(&app);
            app.tab_mut().editing_run.as_mut().expect("editing").buffer = lines.join("\n");
            app.apply_editing_page();
            let after = runs_in_order(&app);
            let new_text = lines[last].clone();
            tests_support::assert_page_after(
                &format!("{path}: the last line retyped"),
                &before,
                &after,
                &[(*first, &new_text)],
                rest,
            );
            let now = after.iter().find(|r| r.object == renumbered(*first, rest)).expect("the last line's first piece");
            assert!(
                now.rect.right < original.right - 3.0,
                "{path}: the last line was stretched: it ends at {:.2}, it ended at {:.2}",
                now.rect.right,
                original.right
            );
        }
        assert!(any, "neither real file is on this machine");
    }

    /// **A ragged (left-aligned) paragraph's lines are not stretched either**: a
    /// word deleted from a line that did not reach the margin leaves it shorter —
    /// it is not spaced out to fill the room it left. (Left-aligned text starts at
    /// one margin like a justified paragraph does; where the lines *end* is what
    /// tells them apart.)
    #[test]
    fn a_ragged_paragraphs_retyped_line_is_not_stretched() {
        let lines: [(f32, f32, &str); 5] = [
            (100.0, 700.0, "alpha beta gamma delta epsilon zeta eta theta"),
            (100.0, 688.0, "iota kappa lambda mu"),
            (100.0, 676.0, "nu xi omicron pi rho sigma tau upsilon phi"),
            (100.0, 664.0, "chi psi omega alpha"),
            (100.0, 652.0, "beta gamma delta epsilon zeta"),
        ];
        let mut app = open_page("ragged", &lines, "");
        pick_object(&mut app, 0);
        let edit = app.tab().editing_run.as_ref().expect("picked").clone();
        assert_eq!(edit.lines.len(), 5, "setup: five lines: {:?}", edit.buffer);
        assert!(
            !paragraph_lines::ends_at_one_margin(&edit.lines),
            "setup: the lines end all over the place: {:?}",
            edit.lines.iter().map(|(_, r)| r.right).collect::<Vec<_>>()
        );
        let original = edit.lines[0].1;
        let mut typed: Vec<String> = edit.buffer.split('\n').map(str::to_string).collect();
        typed[0] = "alpha beta gamma delta epsilon theta".to_string();
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed.join("\n");
        app.apply_editing_page();
        let now = runs_in_order(&app).into_iter().next().expect("the first line");
        assert!(
            now.rect.right < original.right - 10.0,
            "a ragged line was stretched back to its old width: ends at {:.2}, it ended at {:.2}",
            now.rect.right,
            original.right
        );
    }
}

#[cfg(test)]
mod pick_wiring_tests {
    use super::*;
    use pdf_core::document::{Rect, TextRun};

    const MARINA: &str = r"C:\Users\hsili\Desktop\Datasheets - Editors market - Marina mall.pdf";
    const CAMINO: &str = r"C:\Users\hsili\Downloads\CAMINO elitee-plus 3.0.pdf";

    fn fixture(name: &str) -> String {
        format!("{}/../../../rust/pdf_core/fixtures/{name}", env!("CARGO_MANIFEST_DIR"))
    }

    use super::tests_support::one_at_a_time;

    fn app(name: &str) -> PagifyApp {
        let app = PagifyApp::new(Some(&fixture(name)));
        assert!(app.tab().doc.is_some(), "{name} did not open");
        app
    }

    /// The middle of a box, as a click on it.
    fn centre(rect: &Rect) -> AppPoint {
        AppPoint { x: ((rect.left + rect.right) / 2.0) as f64, y: ((rect.top + rect.bottom) / 2.0) as f64 }
    }

    fn text_runs(app: &PagifyApp, page: usize) -> Vec<TextRun> {
        app.tab().doc.as_ref().expect("open").session.text_runs(page).expect("runs")
    }

    /// The session log of `app` redirected to a scratch folder, and where to
    /// read it back from. The folder is the caller's to remove.
    fn log_into(app: &mut PagifyApp, tag: &str) -> (std::path::PathBuf, std::path::PathBuf) {
        let dir = std::env::temp_dir().join(format!("pagify-test-pick-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        app.session_log = pagify_shell::session_log::SessionLog::start_in(dir.clone());
        let path = app.session_log.path().expect("the scratch folder is writable").to_path_buf();
        (dir, path)
    }

    /// The text of every log line of this kind, in order.
    fn logged(path: &std::path::Path, kind: &str) -> Vec<String> {
        std::fs::read_to_string(path)
            .expect("the log file exists")
            .lines()
            .map(|l| serde_json::from_str::<serde_json::Value>(l).expect("valid json"))
            .filter(|l| l["kind"] == kind)
            .map(|l| l["text"].as_str().unwrap_or_default().to_string())
            .collect()
    }

    // -- the user's paragraph ------------------------------------------------

    /// The objects of one block, grouped into the visual lines a person sees —
    /// by baseline, top to bottom, each line left to right. **Worked out from
    /// the page's own words and positions, not from the detector**, so it is a
    /// second opinion on what the detector says.
    fn expected_lines(runs: &HashMap<usize, TextRun>, ids: &[usize]) -> Vec<Vec<usize>> {
        let mut ids = ids.to_vec();
        ids.sort_by(|a, b| runs[a].origin.y.total_cmp(&runs[b].origin.y).then(a.cmp(b)));
        let mut lines: Vec<Vec<usize>> = Vec::new();
        let mut baseline = f32::NAN;
        for id in ids {
            if lines.is_empty() || (runs[&id].origin.y - baseline).abs() > 3.0 {
                baseline = runs[&id].origin.y;
                lines.push(vec![id]);
            } else {
                lines.last_mut().expect("a line").push(id);
            }
        }
        for line in &mut lines {
            line.sort_by(|a, b| runs[a].rect.left.total_cmp(&runs[b].rect.left));
        }
        lines
    }

    /// **The user's own paragraph, on the user's own datasheet.** Page 1 has,
    /// one under the other: a five-line paragraph (objects 951 to 979), a
    /// heading, the 13-line paragraph the user marked in red (985 to 1043 —
    /// 57 text objects, plus two words the page draws as shapes, 1026 and
    /// 1035, which are not text objects at all), and another heading. Clicking
    /// *any* word of any of them has to open exactly that block, whole: the old
    /// geometric walk managed it for none of these 95 words.
    ///
    /// Every one of the 95 words is clicked in turn and each time the editor
    /// must hold: the block's own objects in the block's own lines (worked
    /// out here from the page, see [`expected_lines`]); one buffer line per
    /// line; the words exactly as the page has them, with a hyphen only where
    /// the page has one; the two lines with a drawn word in them frozen and
    /// no others; and the look of the body text — not of the three-letter
    /// "HSI" in another weight inside the first line, and not of the headings.
    ///
    /// Skipped, with a note, where the file is not on this machine.
    #[test]
    fn clicking_any_word_of_the_datasheets_blocks_opens_exactly_that_block() {
        if !std::path::Path::new(MARINA).is_file() {
            eprintln!("skipping: the Marina datasheet is not on this machine");
            return;
        }
        let _turn = one_at_a_time();
        let mut app = PagifyApp::new(Some(MARINA));
        assert!(app.tab().doc.is_some(), "the datasheet is on this machine but would not open");
        let runs: HashMap<usize, TextRun> = text_runs(&app, 0).into_iter().map(|r| (r.object, r)).collect();
        let (page, _) = app.page_blocks(0).expect("the page's blocks");
        let font_of = |object: usize| page.styles[&object].font;
        fn face_key(app: &PagifyApp, object: usize) -> u64 {
            let bytes = app.tab().doc.as_ref().unwrap().session.run_font_data(0, object).unwrap().expect("a font");
            font_key(&bytes)
        }

        // (what it is, its objects, which of its lines draw a word as shapes,
        //  an object that is in the body font / the heading font of the block)
        let blocks: [(&str, std::ops::RangeInclusive<usize>, &[usize], usize); 4] = [
            ("the five-line paragraph", 951..=979, &[], 951),
            ("the heading 'The Light Source - COB'", 980..=984, &[], 981),
            ("the 13-line paragraph marked in red", 985..=1043, &[8, 10], 986),
            ("the heading under it", 1044..=1047, &[], 1045),
        ];
        // The two fonts the test leans on must really be different fonts, or
        // "the body font, not the heading's" would pass for any answer.
        assert_ne!(font_of(986), font_of(981), "setup: the body and the heading are one font");
        assert_ne!(font_of(986), font_of(987), "setup: the 'HSI ' scrap is the body's own font");
        assert_ne!(face_key(&app, 986), face_key(&app, 981), "setup: the body and heading font programs are one");
        assert_ne!(face_key(&app, 986), face_key(&app, 987), "setup: the scrap's font program is the body's");

        let mut ran = 0usize;
        let mut alone = 0usize;
        let mut failures: Vec<String> = Vec::new();
        let mut times: Vec<std::time::Duration> = Vec::new();
        for (name, range, frozen_at, look_of) in blocks {
            let ids: Vec<usize> = range.filter(|o| runs.contains_key(o)).collect();
            let lines = expected_lines(&runs, &ids);
            let frozen: Vec<bool> = (0..lines.len()).map(|i| frozen_at.contains(&i)).collect();
            let texts: Vec<String> = lines
                .iter()
                .map(|line| line.iter().map(|o| runs[o].text.replace(['\r', '\n'], " ")).collect::<String>())
                .collect();
            let want_buffer = fix_extracted_text(&texts.join("\n"));
            let want_font = font_of(look_of);
            let want_face = face_key(&app, look_of);
            eprintln!("{name}: {} words in {} lines", ids.len(), lines.len());

            for &seed in &ids {
                ran += 1;
                app.tab_mut().editing_run = None;
                let started = std::time::Instant::now();
                let outcome = app.pick_text_run(0, centre(&runs[&seed].rect));
                times.push(started.elapsed());
                let who = format!("{name}, clicking object {seed} ({:?})", runs[&seed].text);
                let message = match outcome {
                    Ok(message) => message,
                    Err(why) => {
                        failures.push(format!("{who}: refused: {why}"));
                        continue;
                    }
                };
                let Some(edit) = app.tab().editing_run.as_ref() else {
                    failures.push(format!("{who}: no editor opened"));
                    continue;
                };
                // **A word on a line the page draws part of as shapes opens that
                // word alone**, not the paragraph: in the paragraph its line is
                // frozen — never written — so a box over it could not change the
                // words that were clicked. The paragraph is still one click away on
                // any of its written lines (all the rest of the words, below).
                let own_line = lines.iter().position(|line| line.contains(&seed)).expect("the seed is on a line");
                if frozen_at.contains(&own_line) {
                    alone += 1;
                    if edit.lines != vec![(vec![seed], runs[&seed].rect)] || edit.frozen != [false] {
                        failures.push(format!("{who}: on a frozen line it should open the word alone: {:?}", edit.lines));
                    } else if edit.buffer != fix_extracted_text(&runs[&seed].text) {
                        failures.push(format!("{who}: the word alone reads {:?}", edit.buffer));
                    } else if !message.starts_with("opened this word alone: its line is partly drawn as shapes") {
                        failures.push(format!("{who}: the message does not say why it opened alone: {message}"));
                    }
                    continue;
                }
                let got: Vec<Vec<usize>> = edit.lines.iter().map(|(objects, _)| objects.clone()).collect();
                if got != lines {
                    let flat = |ls: &[Vec<usize>]| ls.iter().flatten().copied().collect::<std::collections::BTreeSet<_>>();
                    failures.push(format!(
                        "{who}: opened {} lines / {} objects, wanted {} lines / {} objects (missing {:?}, extra {:?})",
                        got.len(),
                        flat(&got).len(),
                        lines.len(),
                        ids.len(),
                        flat(&lines).difference(&flat(&got)).collect::<Vec<_>>(),
                        flat(&got).difference(&flat(&lines)).collect::<Vec<_>>()
                    ));
                    continue;
                }
                if edit.buffer.split('\n').count() != edit.lines.len() {
                    failures.push(format!("{who}: {} buffer lines for {} lines", edit.buffer.split('\n').count(), edit.lines.len()));
                }
                if edit.original != edit.buffer {
                    failures.push(format!("{who}: the buffer is not what was picked"));
                }
                if edit.buffer != want_buffer {
                    failures.push(format!("{who}: the words differ from the page's own:\n  got  {:?}\n  want {want_buffer:?}", edit.buffer));
                }
                if edit.frozen != frozen {
                    failures.push(format!("{who}: frozen lines {:?}, wanted {frozen:?}", edit.frozen));
                }
                if edit.object != lines[0][0] {
                    failures.push(format!("{who}: the editor sits on object {}, not the first, {}", edit.object, lines[0][0]));
                }
                if font_of(edit.look_object) != want_font || !ids.contains(&edit.look_object) {
                    failures.push(format!(
                        "{who}: the look comes from object {} (font {}), wanted font {want_font}",
                        edit.look_object,
                        font_of(edit.look_object)
                    ));
                }
                if app.editor_face != Some(want_face) {
                    failures.push(format!("{who}: the editor asked for another font program than the block's own"));
                }
                let drawn = frozen.iter().filter(|f| **f).count();
                if drawn > 0 && !message.contains(&format!("{drawn} lines hold words drawn as shapes")) {
                    failures.push(format!("{who}: the message does not say words are drawn as shapes: {message}"));
                }
                if drawn == 0 && message.contains("drawn as shapes") {
                    failures.push(format!("{who}: the message talks of drawn words where there are none: {message}"));
                }
            }
        }

        times.sort();
        eprintln!(
            "datasheet page 1: {ran} picks — first {:?}, median {:?}, slowest {:?}",
            times.first().copied().unwrap_or_default(),
            times[times.len() / 2],
            times.last().copied().unwrap_or_default()
        );
        assert_eq!(ran, 95, "29 + 5 + 57 + 4 words: has the file changed?");
        assert_eq!(alone, 9, "the words on the two lines with a drawn word in them (4 + 5): has the file changed?");
        assert!(
            failures.is_empty(),
            "{} of {ran} clicks did not open the block they were in:\n{}",
            failures.len(),
            failures.iter().take(12).cloned().collect::<Vec<_>>().join("\n")
        );
    }

    /// **A hyphen before a drawn line stays — in the buffer, and on the page once
    /// the line is retyped.** The datasheet's first paragraph (objects 8 to 16,
    /// "VEGA series is powerful lighting solutions...") has a line the page draws
    /// as shapes between its first and its fourth lines, and the line before it
    /// ends "driv" + the page's hyphen code: the census found the hyphen dropped
    /// from the buffer — so retyping the line would have taken it off the page.
    ///
    /// Checked on the real page: every line of the buffer is the page's own words
    /// with the hyphen code as "-" (including that one); a word of line 1 is
    /// retyped and applied; the retyped piece ends in a real "-" that PDFium reads
    /// back, the apply says it went through, and a click on the paragraph again
    /// opens the same nine lines with the hyphen still there once, not twice.
    ///
    /// Skipped, with a note, where the file is not on this machine.
    #[test]
    fn the_hyphen_before_a_drawn_line_stays_in_the_buffer_and_on_the_page_when_the_line_is_retyped() {
        if !std::path::Path::new(MARINA).is_file() {
            eprintln!("skipping: the Marina datasheet is not on this machine");
            return;
        }
        let _turn = one_at_a_time();
        let mut app = PagifyApp::new(Some(MARINA));
        let runs: HashMap<usize, TextRun> = text_runs(&app, 0).into_iter().map(|r| (r.object, r)).collect();
        assert!(runs[&9].text.ends_with('\u{2}'), "setup: object 9 ends in the hyphen code: {:?}", runs[&9].text);
        app.pick_text_run(0, centre(&runs[&8].rect)).expect("picked");
        let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
        assert_eq!(edit.lines.len(), 9, "setup: the paragraph's nine lines: {:?}", edit.buffer);
        assert_eq!(edit.frozen, [false, false, true, false, false, false, false, false, false]);

        // The page's own words, the hyphen code as "-" wherever there is one.
        let wanted: Vec<String> = edit
            .lines
            .iter()
            .map(|(objects, _)| {
                if objects.is_empty() {
                    block_input::OUTLINED_PLACEHOLDER.to_string()
                } else {
                    objects.iter().map(|o| runs[o].text.replace('\u{2}', "-")).collect()
                }
            })
            .collect();
        let lines: Vec<&str> = edit.buffer.split('\n').collect();
        assert_eq!(lines, wanted, "the buffer is not the page's own words");
        assert!(lines[1].ends_with("COB, driv-"), "the hyphen before the drawn line was dropped: {:?}", lines[1]);

        // Retype a word of that line.
        let mut typed: Vec<String> = lines.iter().map(|l| l.to_string()).collect();
        typed[1] = typed[1].replacen("technology", "technologies", 1);
        assert_ne!(typed[1], lines[1], "setup: the word is on the line");
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed.join("\n");
        app.apply_editing_page();
        let said = app.cmd.history().iter().map(|e| e.text.as_str()).collect::<Vec<_>>().join("\n");
        assert!(said.contains("paragraph changed"), "the apply did not go through:\n{said}");

        // On the page: the retyped piece is the typed words, and the typed "-" is
        // written as the font's own hyphen glyph — the same code the page used
        // before, which this document's broken text mapping reads back as the
        // control code again. So the hyphen is still drawn, as the same glyph, in
        // the line's own font (nothing was substituted).
        let after: HashMap<usize, TextRun> = text_runs(&app, 0).into_iter().map(|r| (r.object, r)).collect();
        assert_eq!(
            after[&9].text,
            typed[1].replace('-', "\u{2}"),
            "what the page now says of that line: the hyphen is no longer the page's own glyph"
        );
        assert!(after[&9].text.ends_with("driv\u{2}"));
        let substituted = app.tab().doc.as_ref().expect("open").session.substituted_face();
        assert_eq!(substituted, None, "the line was written in another font than its own");

        // And the detector still reads it as a hyphenated line end: the same nine
        // lines, the same words, the hyphen once.
        app.tab_mut().editing_run = None;
        app.pick_text_run(0, centre(&after[&8].rect)).expect("picked again");
        let again = app.tab().editing_run.as_ref().expect("an editor opened").clone();
        assert_eq!(again.lines.len(), 9, "the paragraph reopens whole: {:?}", again.buffer);
        let lines_again: Vec<&str> = again.buffer.split('\n').collect();
        assert_eq!(lines_again[1], typed[1], "line 1 reopens as it was typed");
        assert!(!again.buffer.contains("--"), "the hyphen was doubled: {:?}", again.buffer);
    }

    /// **The box takes its look from the font most of the text is set in, by
    /// the page's own identity for the font — not by its name.** The real
    /// datasheet names five different weights "Montserrat-Thin", so a vote on
    /// names sees one font and falls back to the first line's: a paragraph
    /// that starts with a bold scrap would open in bold. Here every object has
    /// the same name and size; only the font ids differ.
    #[test]
    fn the_look_is_the_font_most_of_the_text_is_set_in_even_when_every_font_has_the_same_name() {
        let mut app = app("text-lines.pdf");
        let run = |object: usize, text: &str, top: f32| TextRun {
            object,
            text: text.to_string(),
            rect: Rect { left: 100.0, top, right: 100.0 + 5.0 * text.len() as f32, bottom: top + 10.0 },
            origin: pdf_core::document::Point { x: 100.0, y: top + 8.0 },
            size: 8.0,
            color: pdf_core::document::Color { r: 0, g: 0, b: 0, a: 255 },
        };
        let runs = vec![run(0, "Head", 100.0), run(1, "the body of the paragraph", 112.0), run(2, "more body", 124.0)];
        let names: HashMap<usize, String> = (0..3).map(|o| (o, "Montserrat-Thin".to_string())).collect();
        let lines = || -> Vec<ParagraphLine> {
            runs.iter().map(|r| ParagraphLine { objects: vec![r.object], rect: r.rect, frozen: false }).collect()
        };
        let style = |font: u32| pdf_core::document::RunStyle { font, stem_milli_em: Some(51), axis: (1.0, 0.0) };

        // Object 0 alone in one font, 1 and 2 in another: the second has most of the ink.
        let styles: HashMap<usize, pdf_core::document::RunStyle> =
            [(0, style(3)), (1, style(5)), (2, style(5))].into_iter().collect();
        let (edit, look) = app.build_editor_from_lines(0, lines(), &runs, &names, &styles, &[], None).expect("built");
        assert_eq!(look, 1, "the body's first object, not the first line's");
        assert_eq!(edit.look_object, 1);

        // One font throughout: nothing to outvote, the first object it is.
        let one: HashMap<usize, pdf_core::document::RunStyle> =
            [(0, style(5)), (1, style(5)), (2, style(5))].into_iter().collect();
        let (edit, look) = app.build_editor_from_lines(0, lines(), &runs, &names, &one, &[], None).expect("built");
        assert_eq!((look, edit.look_object), (0, 0));
    }

    /// **The whole of what the user asked for, on the user's own paragraph:
    /// click a word of it, retype one line, apply — and only that line
    /// changes.** The 13-line paragraph of page 1 (objects 985 to 1043) has
    /// lines of three to eight pieces, two lines with a word the page draws
    /// as shapes, and a hyphen glyph at the end of five of them. One middle
    /// line made of plain words is retyped by repeating a word it already
    /// has (so no letter the font lacks is needed); every other line's objects
    /// must hold exactly the words and colour they held, the retyped line's
    /// other pieces are removed from the page, and nothing else is.
    #[test]
    fn retyping_one_line_of_the_datasheets_paragraph_writes_only_that_line() {
        if !std::path::Path::new(MARINA).is_file() {
            eprintln!("skipping: the Marina datasheet is not on this machine");
            return;
        }
        let _turn = one_at_a_time();
        let mut app = PagifyApp::new(Some(MARINA));
        assert!(app.tab().doc.is_some(), "the datasheet is on this machine but would not open");
        let runs: HashMap<usize, TextRun> = text_runs(&app, 0).into_iter().map(|r| (r.object, r)).collect();
        app.pick_text_run(0, centre(&runs[&986].rect)).expect("picked");
        let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
        assert_eq!(edit.lines.len(), 13, "setup: the user's paragraph");

        // Line 3, "lighting industry conforming": plain words, several pieces.
        let target = 3;
        let typed_lines: Vec<String> = edit.buffer.split('\n').map(str::to_string).collect();
        assert!(typed_lines[target].starts_with("lighting industry"), "setup: {:?}", typed_lines[target]);
        assert!(edit.lines[target].0.len() > 1, "setup: the line is made of several pieces");
        let mut retyped = typed_lines.clone();
        retyped[target] = format!("{} industry", typed_lines[target].trim_end());

        let before = tests_support::runs_in_order(&app);
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped.join("\n");
        let started = std::time::Instant::now();
        app.apply_editing_page();
        eprintln!("timing: retyping one line of the 13-line datasheet paragraph took {:?}", started.elapsed());
        let said = app.cmd.history().iter().map(|e| e.text.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            said.contains("paragraph changed"),
            "the apply did not go through — the engine must be able to write every object of the line:\n{said}"
        );
        let after = tests_support::runs_in_order(&app);

        // The retyped line is its first piece holding the new words and its
        // other pieces are gone from the page (they were painted in the page's
        // colour, which left their old words in the file); every other object
        // — every piece of every other line, and everything outside the
        // paragraph — holds exactly the words, colour and place it held.
        let (first, rest) = edit.lines[target].0.split_first().expect("the line has objects");
        tests_support::assert_page_after(
            "one line of the datasheet's paragraph",
            &before,
            &after,
            &[(*first, &retyped[target])],
            rest,
        );
    }

    // -- the log -------------------------------------------------------------

    /// Click once; what came of it and the one log line it wrote.
    fn click_logged(
        app: &mut PagifyApp,
        log: &std::path::Path,
        page: usize,
        at: AppPoint,
    ) -> (Result<String, String>, String) {
        let before = logged(log, "pick").len();
        let outcome = app.pick_text_run(page, at);
        let lines = logged(log, "pick");
        assert_eq!(lines.len(), before + 1, "a click must write exactly one pick line: {lines:?}");
        (outcome, lines.last().cloned().expect("a line"))
    }

    /// `key=value` out of a pick line (values hold no spaces).
    fn field<'a>(line: &'a str, key: &str) -> &'a str {
        line.split(' ')
            .find_map(|pair| pair.strip_prefix(key).and_then(|rest| rest.strip_prefix('=')))
            .unwrap_or_else(|| panic!("no `{key}=` in {line:?}"))
    }

    /// **Every click leaves exactly one `pick` line in the session log, on
    /// whichever way it goes** — a paragraph, one run, a joined group, a word
    /// drawn as outlines, rotated text refused, nothing there — and the line
    /// holds ids, counts, geometry and times, never a word of the page.
    #[test]
    fn every_click_writes_exactly_one_content_free_pick_line_to_the_session_log() {
        let _turn = one_at_a_time();
        // -- a paragraph, then the same click again -------------------------
        let mut app = app("two-column.pdf");
        let (dir, log) = log_into(&mut app, "paths");
        let runs = text_runs(&app, 0);
        let mut left: Vec<TextRun> = runs.iter().filter(|r| r.rect.left < 300.0).cloned().collect();
        left.sort_by(|a, b| a.rect.top.total_cmp(&b.rect.top));
        let middle = left[left.len() / 2].clone();
        let at = centre(&middle.rect);

        let (outcome, line) = click_logged(&mut app, &log, 0, at);
        assert!(outcome.is_ok(), "{outcome:?}");
        assert_eq!(field(&line, "path"), "block", "{line}");
        assert_eq!(field(&line, "seed"), middle.object.to_string(), "{line}");
        assert_eq!(field(&line, "rule"), "exact", "{line}");
        assert_eq!((field(&line, "lines"), field(&line, "objects"), field(&line, "frozen")), ("8", "8", "[]"), "{line}");
        assert_eq!(field(&line, "cache"), "miss", "the first click on a page reads it: {line}");
        assert!(line.starts_with("page 1 click=("), "{line}");
        assert!(field(&line, "frags").parse::<usize>().unwrap() >= 8, "{line}");
        assert!(field(&line, "total_ms").parse::<f32>().unwrap() >= 0.0, "{line}");
        // Content-free: not one word of what was clicked on.
        for run in &left {
            for word in run.text.split_whitespace().filter(|w| w.chars().count() >= 4) {
                assert!(!line.contains(word), "the log line holds the page's own word {word:?}: {line}");
            }
        }
        let block = field(&line, "block").to_string();

        let (_, again) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&again, "cache"), "hit", "nothing changed since the page was read: {again}");
        assert_eq!(field(&again, "block"), block, "{again}");

        // -- a joined group ---------------------------------------------------
        let (a, b) = (
            runs.iter().min_by(|x, y| x.rect.top.total_cmp(&y.rect.top)).unwrap().clone(),
            runs.iter().max_by(|x, y| x.rect.top.total_cmp(&y.rect.top)).unwrap().clone(),
        );
        let total = app.characters(0).expect("characters").len();
        app.tab_mut().text_selection = Some(0..total);
        app.tab_mut().selection_page = 0;
        app.join_selected_text().expect("join");
        app.tab_mut().editing_run = None;
        let (outcome, line) = click_logged(&mut app, &log, 0, centre(&b.rect));
        assert!(outcome.is_ok(), "{outcome:?}");
        assert_eq!(field(&line, "path"), "joined", "{line}");
        assert_eq!(field(&line, "seed"), b.object.to_string(), "{line}");
        let _ = a;
        let _ = std::fs::remove_dir_all(&dir);

        // -- one run alone, and bare paper -------------------------------------
        let (mut single, (dir, log)) = app_with_log("text-lines.pdf", "single");
        let only = text_runs(&single, 0)[0].clone();
        let (outcome, line) = click_logged(&mut single, &log, 0, centre(&only.rect));
        assert!(outcome.expect("picked").starts_with("edit the words on the page"), "{line}");
        assert_eq!(field(&line, "path"), "single", "{line}");
        assert_eq!((field(&line, "lines"), field(&line, "objects")), ("1", "1"), "a block of one object: {line}");

        let (outcome, line) = click_logged(&mut single, &log, 0, AppPoint { x: 3.0, y: 3.0 });
        assert!(outcome.expect_err("bare paper").contains("no text there"), "{line}");
        assert_eq!(field(&line, "path"), "none", "{line}");
        assert_eq!((field(&line, "seed"), field(&line, "block")), ("none", "none"), "{line}");
        let _ = std::fs::remove_dir_all(&dir);

        // -- a word drawn as outlines -------------------------------------------
        let (mut outlined, (dir, log)) = app_with_log("outlined-montserrat.pdf", "drawn");
        let word = outlined
            .drawn_words_on(0)
            .iter()
            .filter(|w| !w.text.trim().is_empty())
            .max_by_key(|w| w.text.trim().chars().count())
            .cloned()
            .expect("a recognised word");
        let (outcome, line) = click_logged(&mut outlined, &log, 0, centre(&word.rect));
        assert!(outcome.expect("picked").contains("drawn, not written"), "{line}");
        assert_eq!(field(&line, "path"), "drawn", "{line}");
        assert_eq!(
            (field(&line, "frags"), field(&line, "blocks"), field(&line, "seed")),
            ("0", "0", "none"),
            "no text objects on this page: {line}"
        );
        let _ = std::fs::remove_dir_all(&dir);

        // -- rotated text, refused (needs the real file) ---------------------------
        if !std::path::Path::new(CAMINO).is_file() {
            eprintln!("skipping the rotated-text case: CAMINO is not on this machine");
            return;
        }
        let mut camino = PagifyApp::new(Some(CAMINO));
        let (dir, log) = log_into(&mut camino, "rotated");
        let pages = camino.tab().doc.as_ref().expect("open").page_count;
        let rotated = (0..pages).find_map(|p| {
            text_runs(&camino, p)
                .into_iter()
                .find(|r| looks_rotated(&r.rect, r.text.trim().chars().count()))
                .map(|r| (p, r))
        });
        let Some((page, run)) = rotated else {
            eprintln!("skipping the rotated-text case: CAMINO has no rotated label");
            return;
        };
        let (outcome, line) = click_logged(&mut camino, &log, page, centre(&run.rect));
        assert!(outcome.expect_err("refused").contains("rotated"), "{line}");
        assert_eq!(field(&line, "path"), "refused-rotated", "{line}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    fn app_with_log(name: &str, tag: &str) -> (PagifyApp, (std::path::PathBuf, std::path::PathBuf)) {
        let mut app = app(name);
        let log = log_into(&mut app, tag);
        (app, log)
    }

    // -- a page that moved, and a page that cannot be read --------------------

    /// **A page read before an edit, an undo or a redo is never used after
    /// it.** The reading is cached per page and stamped with the document's
    /// render epoch and the session's undo generation; both are checked, so a
    /// page changed behind the app's back — straight through the session, as
    /// the tests (and any path that forgets to say so) do — is still read
    /// afresh. A stale reading would show the words as they were, and
    /// object numbers that no longer mean what they did.
    #[test]
    fn a_page_read_before_an_edit_or_an_undo_is_not_used_after_it() {
        let (mut app, (dir, log)) = app_with_log("text-lines.pdf", "stale");
        let first = text_runs(&app, 0)[0].clone();
        // Just inside the left end of the run: still inside it after its words change.
        let at = AppPoint { x: (first.rect.left + 3.0) as f64, y: ((first.rect.top + first.rect.bottom) / 2.0) as f64 };
        let session = app.tab().doc.as_ref().expect("open").session.clone();

        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "miss", "{line}");
        assert_eq!(app.tab().editing_run.as_ref().expect("picked").buffer.trim(), first.text.trim());
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "hit", "nothing moved: {line}");

        // Changed behind the app's back: no `rendered_is_stale`, no epoch move.
        session
            .execute(pdf_core::command::Command::SetTextRun {
                page_index: 0,
                object: first.object,
                text: "CHANGED UNDERNEATH THE CACHE".to_string(),
                style: Default::default(),
            })
            .expect("edit through the session");
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "miss", "the history moved, so the page is read again: {line}");
        assert_eq!(
            app.tab().editing_run.as_ref().expect("picked").buffer.trim(),
            "CHANGED UNDERNEATH THE CACHE",
            "a stale reading would still offer the old words"
        );

        // And back, the same way.
        let (undone, _) = session.undo().expect("undo");
        assert!(undone);
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "miss", "{line}");
        assert_eq!(app.tab().editing_run.as_ref().expect("picked").buffer.trim(), first.text.trim());
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "hit", "{line}");

        // Through the app's own paths: an apply, then the app's own undo.
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = "TYPED IN THE BOX".to_string();
        app.apply_editing_page();
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "miss", "an apply makes the next click read the page again: {line}");
        assert_eq!(app.tab().editing_run.as_ref().expect("picked").buffer.trim(), "TYPED IN THE BOX");
        app.tab_mut().editing_run = None;
        app.submit("undo");
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "miss", "{line}");
        assert_eq!(app.tab().editing_run.as_ref().expect("picked").buffer.trim(), first.text.trim());
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The other half of the cache's key, and of its clearing. Splitting a run
    /// into its letters is the one page change that does not go through the
    /// history (it moves no undo generation); what makes the next click read
    /// the page again is [`Doc::rendered_is_stale`], which the app calls right
    /// after — the render epoch it moves, and the cache it empties.
    #[test]
    fn a_page_changed_outside_the_history_is_read_again_once_it_is_declared_stale() {
        let (mut app, (dir, log)) = app_with_log("text-lines.pdf", "split");
        let first = text_runs(&app, 0)[0].clone();
        let at = AppPoint { x: (first.rect.left + 2.0) as f64, y: ((first.rect.top + first.rect.bottom) / 2.0) as f64 };
        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!((field(&line, "objects"), field(&line, "cache")), ("1", "miss"), "{line}");

        let session = app.tab().doc.as_ref().expect("open").session.clone();
        let generation = session.undo_generation();
        session.split_run_into_characters(0, first.object).expect("split");
        assert_eq!(session.undo_generation(), generation, "setup: a split does not move the history");
        app.tab_mut().doc.as_mut().expect("open").rendered_is_stale();

        let (_, line) = click_logged(&mut app, &log, 0, at);
        assert_eq!(field(&line, "cache"), "miss", "{line}");
        assert!(
            field(&line, "objects").parse::<usize>().unwrap() > 1,
            "the letters of the split run are the page now: {line}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **Edit Text never stops working.** If the page's text cannot be read in
    /// one pass the click falls back to what the tool always did: the one run
    /// under the pointer, found from the boxes alone — no paragraph, no
    /// detector. The log says it happened.
    #[test]
    fn edit_text_still_opens_the_run_when_the_pages_text_cannot_be_read_in_one_pass() {
        struct Restore;
        impl Drop for Restore {
            fn drop(&mut self) {
                tests_support::SNAPSHOT_FAILS.with(|fails| fails.set(false));
            }
        }
        let _restore = Restore;

        let (mut app, (dir, log)) = app_with_log("two-column.pdf", "fallback");
        let runs = text_runs(&app, 0);
        let mut left: Vec<TextRun> = runs.iter().filter(|r| r.rect.left < 300.0).cloned().collect();
        left.sort_by(|a, b| a.rect.top.total_cmp(&b.rect.top));
        let middle = left[left.len() / 2].clone();

        tests_support::SNAPSHOT_FAILS.with(|fails| fails.set(true));
        let (outcome, line) = click_logged(&mut app, &log, 0, centre(&middle.rect));
        assert!(outcome.expect("still picked").starts_with("edit the words on the page"), "{line}");
        let edit = app.tab().editing_run.as_ref().expect("an editor opened");
        assert_eq!(edit.lines, vec![(vec![middle.object], middle.rect)], "the run alone, not its paragraph");
        assert_eq!(edit.buffer.trim(), middle.text.trim());
        assert_eq!(field(&line, "path"), "single", "{line}");
        assert_eq!((field(&line, "frags"), field(&line, "blocks"), field(&line, "block")), ("0", "0", "none"), "{line}");
        assert_eq!(field(&line, "seed"), middle.object.to_string(), "{line}");
        let notes = logged(&log, "pick-note");
        assert_eq!(notes.len(), 1, "{notes:?}");
        assert!(notes[0].contains("picking the run alone"), "{notes:?}");

        // Bare paper is still bare paper.
        let (outcome, line) = click_logged(&mut app, &log, 0, AppPoint { x: 3.0, y: 3.0 });
        assert!(outcome.expect_err("nothing there").contains("no text there"), "{line}");
        assert_eq!(field(&line, "path"), "none", "{line}");

        // And the moment it can be read again, the paragraph is back.
        tests_support::SNAPSHOT_FAILS.with(|fails| fails.set(false));
        app.tab_mut().editing_run = None;
        let (_, line) = click_logged(&mut app, &log, 0, centre(&middle.rect));
        assert_eq!((field(&line, "path"), field(&line, "lines")), ("block", "8"), "{line}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **The small picture a paragraph's background colour is sampled from is
    /// made once per state of the page, not once per click.** A render is the
    /// bulk of what a click costs once the page has been read, and every click
    /// on one page wants the same picture. It is kept under the same key as the
    /// page's reading — page, render epoch, undo generation — so an edit, an
    /// undo or a declared change makes the next click render the page as it is
    /// now, and a hide colour is never sampled from a picture of what was.
    #[test]
    fn the_background_is_sampled_from_one_picture_per_state_of_the_page() {
        let mut app = app("two-column.pdf");
        let kept = |app: &PagifyApp| {
            app.tab().doc.as_ref().expect("open").sampling.borrow().as_ref().map(|(_, picture)| picture.clone())
        };
        let mut left: Vec<TextRun> = text_runs(&app, 0).into_iter().filter(|r| r.rect.left < 300.0).collect();
        left.sort_by(|a, b| a.rect.top.total_cmp(&b.rect.top));
        assert!(kept(&app).is_none(), "nothing is rendered before the first click");

        app.pick_text_run(0, centre(&left[1].rect)).expect("picked");
        let first = kept(&app).expect("a picture was kept");
        app.pick_text_run(0, centre(&left[5].rect)).expect("picked");
        assert!(
            std::rc::Rc::ptr_eq(&first, &kept(&app).expect("still kept")),
            "a second click on the same page made a picture of its own"
        );

        // The page moves: the next click makes a new picture.
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = "ONE\nTWO\nTHREE\nFOUR\nFIVE\nSIX\nSEVEN\nEIGHT".to_string();
        app.apply_editing_page();
        assert!(kept(&app).is_none(), "an apply leaves the old picture behind");
        // At the left end of a line: the words there are short now.
        let at_left = |r: &Rect| AppPoint { x: (r.left + 2.0) as f64, y: ((r.top + r.bottom) / 2.0) as f64 };
        app.pick_text_run(0, at_left(&left[1].rect)).expect("picked");
        let second = kept(&app).expect("a picture was kept");
        assert!(!std::rc::Rc::ptr_eq(&first, &second), "the picture is of the page before the edit");

        // Behind the app's back, as the stale-cache test does: only the key can tell.
        let session = app.tab().doc.as_ref().expect("open").session.clone();
        let (undone, _) = session.undo().expect("undo");
        assert!(undone);
        app.pick_text_run(0, at_left(&left[1].rect)).expect("picked");
        assert!(
            !std::rc::Rc::ptr_eq(&second, &kept(&app).expect("a picture was kept")),
            "an undo made behind the app's back left the old picture in use"
        );
    }

    /// **A page with no text objects at all is not an error.** Its reading is
    /// empty (no shapes either: a page of outlines has tens of thousands, and
    /// there is no text to bridge between them), and a click on one of its
    /// drawn words still reaches [`PagifyApp::drawn_word_at`] — the only way to
    /// edit words that are artwork — while bare paper still says there is no
    /// text there.
    #[test]
    fn a_page_with_no_text_objects_still_reaches_the_drawn_words() {
        let _turn = one_at_a_time();
        let (mut app, (dir, log)) = app_with_log("outlined-montserrat.pdf", "no-text");
        let (page, _) = app.page_blocks(0).expect("an empty page reads fine");
        assert!(
            page.runs.is_empty() && page.frags.is_empty() && page.blocks.is_empty() && page.shapes.is_empty(),
            "setup: this page has no text objects, so nothing is read from it"
        );
        let word = app
            .drawn_words_on(0)
            .iter()
            .filter(|w| !w.text.trim().is_empty())
            .max_by_key(|w| w.text.trim().chars().count())
            .cloned()
            .expect("a recognised word");

        let (outcome, line) = click_logged(&mut app, &log, 0, centre(&word.rect));
        assert!(outcome.expect("a drawn word").contains("drawn, not written"), "{line}");
        assert!(app.tab().editing_run.as_ref().expect("an editor opened").drawn);
        assert_eq!(field(&line, "path"), "drawn", "{line}");

        app.tab_mut().editing_run = None;
        let (outcome, line) = click_logged(&mut app, &log, 0, AppPoint { x: 2.0, y: 2.0 });
        let said = outcome.expect_err("bare paper");
        assert!(said.contains("no text there"), "{said}");
        assert_eq!(field(&line, "path"), "none", "{line}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    // -- lines drawn as shapes -------------------------------------------------

    /// **A paragraph with whole lines drawn as shapes opens whole, and shows
    /// where the drawn lines are.** Page 1 of the datasheet has a 19-line,
    /// 96-object block whose lines 4, 14 and 18 (counting from 0) are drawn
    /// entirely as outlines — ligature-heavy body lines the producer
    /// converted to paths — so they have no text object at all. They must be
    /// in the editor as lines (the box is one line per line of the block,
    /// or an apply would pair every later line with the wrong objects), each
    /// as the placeholder standing for words that cannot be retyped here, and
    /// the pick has to say so.
    #[test]
    fn a_block_with_whole_lines_drawn_as_shapes_opens_whole_with_a_placeholder_for_each() {
        if !std::path::Path::new(MARINA).is_file() {
            eprintln!("skipping: the Marina datasheet is not on this machine");
            return;
        }
        let _turn = one_at_a_time();
        let mut app = PagifyApp::new(Some(MARINA));
        assert!(app.tab().doc.is_some(), "the datasheet is on this machine but would not open");
        let (page, _) = app.page_blocks(0).expect("the page's blocks");
        // **Changed for what the detector and the adapter read now, with the reason**:
        // the thin glyphs of the page (a hyphen 2 points wide, an "l" 0.4 point wide)
        // are members of their lines — they used to be left out of the buffer — so
        // the line the page ends in a hyphen after a drawn word (line 14) is an
        // outlined word *and* the hyphen glyph, a text object: the line is frozen
        // but is no longer without an object. Lines 4 and 18 are still drawn with
        // nothing written in them. What the test protects is unchanged: the whole
        // block opens, with a placeholder for each line that has no text.
        let (index, block) = page
            .blocks
            .iter()
            .enumerate()
            .find(|(_, b)| b.lines.len() == 19 && b.lines.iter().filter(|l| !l.outlined.is_empty()).count() == 3)
            .expect("the 19-line block with three lines drawn as shapes is gone from page 1 — has the detector or the file changed?");
        let drawn_lines: Vec<usize> =
            block.lines.iter().enumerate().filter(|(_, l)| l.objects.is_empty()).map(|(i, _)| i).collect();
        let frozen_lines: Vec<usize> =
            block.lines.iter().enumerate().filter(|(_, l)| !l.outlined.is_empty()).map(|(i, _)| i).collect();
        assert_eq!(drawn_lines, [4, 18], "setup: block {index}: the lines with no text object");
        assert_eq!(frozen_lines, [4, 14, 18], "setup: block {index}: the lines with drawn words");

        // Clicked from every one of its words, so every line is tried as the seed.
        let (mut clicked, mut alone) = (0, 0);
        for (line_index, line) in block.lines.iter().enumerate() {
            for &seed in &line.objects {
                app.tab_mut().editing_run = None;
                let said = app.pick_text_run(0, centre(&page.runs[&seed].rect)).expect("picked");
                let edit = app.tab().editing_run.as_ref().expect("an editor opened");
                clicked += 1;
                // A word on a line that is partly drawn opens alone — see
                // `clicking_any_word_of_the_datasheets_blocks_opens_exactly_that_block`.
                if frozen_lines.contains(&line_index) {
                    alone += 1;
                    assert_eq!(edit.lines.len(), 1, "clicking object {seed} on a drawn line: {said}");
                    assert!(said.starts_with("opened this word alone: its line is partly drawn"), "{said}");
                    continue;
                }
                assert_eq!(edit.lines.len(), 19, "clicking object {seed}: {said}");
                assert_eq!(edit.buffer.split('\n').count(), 19, "one buffer line for every line, drawn ones included");
                for i in 0..19 {
                    assert_eq!(edit.frozen[i], frozen_lines.contains(&i), "clicking object {seed}: line {i}");
                    let drawn = drawn_lines.contains(&i);
                    assert_eq!(edit.lines[i].0.is_empty(), drawn, "clicking object {seed}: line {i}");
                    assert_eq!(
                        edit.buffer.split('\n').nth(i) == Some(block_input::OUTLINED_PLACEHOLDER),
                        drawn,
                        "clicking object {seed}: line {i} of the buffer is {:?}",
                        edit.buffer.split('\n').nth(i)
                    );
                }
                assert!(said.contains("editing a paragraph of 19 lines"), "{said}");
                assert!(said.contains("3 lines hold words drawn as shapes and are left exactly as they are"), "{said}");
            }
        }
        assert_eq!(clicked, 99, "every word of the block was clicked");
        assert_eq!(alone, 1, "the one text object on a drawn line: the hyphen glyph");
    }

    /// **An apply never touches a line drawn as shapes.** A four-line block of
    /// page 1 — a line of text, two lines drawn entirely as outlines, and a
    /// last line of text (`given project.`) — has one text object on each of
    /// its text lines. One is retyped and the placeholder of a drawn line is
    /// typed over: only the retyped line is written, the typed-over one is
    /// reported as left alone, and every other object — and every shape on the
    /// page — is exactly as it was.
    #[test]
    fn retyping_beside_lines_drawn_as_shapes_writes_only_the_retyped_line() {
        if !std::path::Path::new(MARINA).is_file() {
            eprintln!("skipping: the Marina datasheet is not on this machine");
            return;
        }
        let _turn = one_at_a_time();
        let mut app = PagifyApp::new(Some(MARINA));
        assert!(app.tab().doc.is_some(), "the datasheet is on this machine but would not open");
        let (page, _) = app.page_blocks(0).expect("the page's blocks");
        let block = page
            .blocks
            .iter()
            // **Selected by which lines are drawn, not by which have no text object**
            // (changed with the reason): the hyphen glyph the page ends the first drawn
            // line with is a member of its line now, so that line has one text object
            // (a "-", frozen like the rest of the line) where it had none.
            .find(|b| {
                b.lines.len() == 4
                    && b.lines[0].objects.len() == 1
                    && b.lines[0].outlined.is_empty()
                    && !b.lines[1].outlined.is_empty()
                    && !b.lines[2].outlined.is_empty()
                    && b.lines[2].objects.is_empty()
                    && b.lines[3].outlined.is_empty()
                    && b.lines[3].objects.len() == 1
            })
            .expect("the text / drawn / drawn / text block is gone from page 1 — has the detector or the file changed?");
        let (first, last) = (block.lines[0].objects[0], block.lines[3].objects[0]);
        let shapes_before = app.tab().doc.as_ref().unwrap().session.drawn_objects(0).expect("shapes").len();

        let said = app.pick_text_run(0, centre(&page.runs[&first].rect)).expect("picked");
        assert!(said.contains("2 lines hold words drawn as shapes"), "{said}");
        let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
        assert_eq!(edit.frozen, [false, true, true, false]);
        // **The hyphen glyph that is the whole text of the first drawn line stays in
        // the buffer, on a line of its own** — not dropped (the line would then read
        // empty, and be taken for a line with nothing on it), not doubled, not run
        // into the neighbouring lines. The placeholder stands for the line with no
        // text object at all.
        let buffer_lines: Vec<&str> = edit.buffer.split('\n').collect();
        assert_eq!(buffer_lines.len(), 4, "{:?}", edit.buffer);
        assert_eq!(buffer_lines[1], "-", "{:?}", edit.buffer);
        assert_eq!(buffer_lines[2], block_input::OUTLINED_PLACEHOLDER, "{:?}", edit.buffer);

        let words_before: HashMap<usize, (String, pdf_core::document::Color)> =
            text_runs(&app, 0).into_iter().map(|r| (r.object, (r.text, r.color))).collect();
        let mut typed: Vec<String> = edit.buffer.split('\n').map(str::to_string).collect();
        typed[0] = format!("{} RETYPED", typed[0].trim_end());
        typed[1] = "typed over a line that is drawn".to_string();
        app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed.join("\n");
        app.apply_editing_page();

        let said_after = app.cmd.history().iter().map(|e| e.text.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            said_after.contains("paragraph changed; 1 line drawn as shapes was left as it is."),
            "the apply did not say what it left alone:\n{said_after}"
        );
        let words_after: HashMap<usize, (String, pdf_core::document::Color)> =
            text_runs(&app, 0).into_iter().map(|r| (r.object, (r.text, r.color))).collect();
        assert_eq!(words_after.len(), words_before.len(), "objects were added or lost");
        assert!(words_after[&first].0.contains("RETYPED"), "the retyped line was not written: {:?}", words_after[&first].0);
        assert_eq!(words_after[&last], words_before[&last], "the line after the drawn ones was touched");
        for (object, was) in &words_before {
            if *object != first {
                assert_eq!(&words_after[object], was, "object {object}, which is not on the retyped line, changed");
            }
        }
        let shapes_after = app.tab().doc.as_ref().unwrap().session.drawn_objects(0).expect("shapes").len();
        assert_eq!(shapes_after, shapes_before, "a shape was added or taken off the page");
    }

    /// **A guard, run on demand: retype one line in every paragraph of a file,
    /// and nothing else on its page may change.**
    ///
    /// For every block of more than one text object on the first
    /// `PAGIFY_SWEEP_PAGES` pages (default 1) of `PAGIFY_SWEEP_PDF` (default
    /// the datasheet) — in a freshly opened copy of the file each time, so one
    /// block's edit cannot show in the next — a word of it is clicked and its
    /// first line of plain words is retyped by repeating a word it already has
    /// (so no letter the font lacks is needed), then applied. The retyped line
    /// must be its first piece holding the new words, its other pieces must be
    /// gone from the page, and every other object on the page — every piece of
    /// every other line, words, colour, box, origin and size — must be exactly
    /// as it was, the page having lost exactly the pieces removed. The engine refusing an edit — safely and whole, for
    /// text it cannot map to the operators that draw it — is counted and said,
    /// not failed on; an edit that goes through and leaves anything else
    /// different is the failure.
    ///
    /// `cargo test -p pagify_app --release apply_sweep -- --ignored --nocapture`
    #[test]
    #[ignore = "a sweep that takes a minute or more: run with --ignored --nocapture"]
    fn apply_sweep() {
        let path = std::env::var("PAGIFY_SWEEP_PDF").unwrap_or_else(|_| MARINA.to_string());
        if !std::path::Path::new(&path).is_file() {
            eprintln!("sweep: skipping, {path} is not on this machine");
            return;
        }
        let pages: usize = std::env::var("PAGIFY_SWEEP_PAGES").ok().and_then(|v| v.parse().ok()).unwrap_or(1);
        let mut app = PagifyApp::new(Some(&path));
        let page_total = app.tab().doc.as_ref().expect("open").page_count;
        let words = |text: &str| text.split_whitespace().find(|w| w.chars().count() > 2 && w.chars().all(char::is_alphabetic)).map(str::to_string);
        let mut tally: std::collections::BTreeMap<String, usize> = Default::default();
        let mut damaged: Vec<String> = Vec::new();
        let mut refused: Vec<String> = Vec::new();
        for page in 0..pages.min(page_total) {
            let (page_blocks, _) = app.page_blocks(page).expect("the page's blocks");
            for (index, block) in page_blocks.blocks.iter().enumerate().filter(|(_, b)| b.objects().len() > 1) {
                app = PagifyApp::new(Some(&path));
                if app.pick_text_run(page, centre(&page_blocks.runs[&block.objects()[0]].rect)).is_err() {
                    *tally.entry("the click was refused".into()).or_default() += 1;
                    continue;
                }
                let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
                let typed: Vec<String> = edit.buffer.split('\n').map(str::to_string).collect();
                let Some(target) = (0..typed.len()).find(|&i| !edit.frozen[i] && !edit.lines[i].0.is_empty() && words(&typed[i]).is_some()) else {
                    *tally.entry("no line of plain words to retype".into()).or_default() += 1;
                    continue;
                };
                let mut retyped = typed.clone();
                retyped[target] = format!("{} {}", typed[target].trim_end(), words(&typed[target]).expect("a word"));
                let before = tests_support::runs_on_page(&app, page);
                app.tab_mut().editing_run.as_mut().expect("editing").buffer = retyped.join("\n");
                let history = app.cmd.history().len();
                app.apply_editing_page();
                let said: Vec<String> = app.cmd.history().iter().skip(history).map(|e| e.text.clone()).collect();
                if !said.iter().any(|s| s.contains("paragraph changed")) {
                    let why: String = said.last().map_or(String::new(), |s| s.chars().take(100).collect());
                    *tally.entry(format!("refused by the engine: {why}")).or_default() += 1;
                    refused.push(format!("page {} block {index} line {target}: {why}", page + 1));
                    continue;
                }
                // The retyped line is its first piece holding the new words,
                // its other pieces are gone from the page, and every other
                // object — every piece of every other line, and everything
                // outside the paragraph — is as it was.
                let after = tests_support::runs_on_page(&app, page);
                let (first, rest) = edit.lines[target].0.split_first().expect("the line has objects");
                match tests_support::page_after_problem(&before, &after, &[(*first, &retyped[target])], rest) {
                    None => *tally.entry("ok".into()).or_default() += 1,
                    Some(wrong) => {
                        *tally.entry("DAMAGED".into()).or_default() += 1;
                        damaged.push(format!("page {} block {index} line {target}: {wrong}", page + 1));
                    }
                }
            }
        }
        for (what, n) in &tally {
            eprintln!("sweep: {n:4} {what}");
        }
        assert!(tally.get("ok").copied().unwrap_or(0) > 0, "the sweep retyped nothing: {tally:?}");
        assert!(damaged.is_empty(), "{} edits changed more than the line retyped:\n{}", damaged.len(), damaged.join("\n"));
        // On the datasheet itself — the file this was built for — not one paragraph may be refused.
        if std::env::var("PAGIFY_SWEEP_PDF").is_err() {
            assert!(refused.is_empty(), "{} paragraphs of the datasheet could not be retyped:\n{}", refused.len(), refused.join("\n"));
        }
    }

    // -- what a click costs ------------------------------------------------------

    /// **A measurement, not a check: what a click costs.** Per page of the
    /// datasheet and of CAMINO: arming Edit Text, the first click on the page
    /// (which reads it), the clicks after it (which do not), and one render of
    /// the page at the sampling scale that every paragraph pick pays for. Run
    /// it alone — `cargo test -p pagify_app --release pick_timings -- --ignored
    /// --nocapture` — since the PDFium lock is one for the whole process and
    /// any other test running beside it shows up as a wait.
    #[test]
    #[ignore = "a measurement: run alone with --ignored --nocapture"]
    fn pick_timings() {
        for (name, path) in [("datasheet", MARINA), ("CAMINO", CAMINO)] {
            if !std::path::Path::new(path).is_file() {
                eprintln!("timing: skipping the {name}: it is not on this machine");
                continue;
            }
            let mut app = PagifyApp::new(Some(path));
            let (dir, log) = log_into(&mut app, "timings");
            let started = std::time::Instant::now();
            app.submit("edittext");
            eprintln!("timing: {name}: arming Edit Text took {:?}", started.elapsed());
            let pages = app.tab().doc.as_ref().expect("open").page_count.min(3);
            let mut after = 0u64;
            for page in 0..pages {
                let runs = text_runs(&app, page);
                // A spread of paragraphs: every 25th run that has words in it.
                let targets: Vec<&TextRun> =
                    runs.iter().filter(|r| r.text.trim().chars().count() > 4).step_by(25).take(24).collect();
                let mut later: Vec<std::time::Duration> = Vec::new();
                for (i, run) in targets.iter().enumerate() {
                    app.tab_mut().editing_run = None;
                    let started = std::time::Instant::now();
                    let _ = app.pick_text_run(page, centre(&run.rect));
                    let took = started.elapsed();
                    let line = newest_pick_line(&log, &mut after);
                    if i == 0 {
                        eprintln!("timing: {name} page {}: first click, which reads the page: {took:?}  [{line}]", page + 1);
                    } else {
                        later.push(took);
                    }
                }
                later.sort();
                if !later.is_empty() {
                    eprintln!(
                        "timing: {name} page {}: {} clicks after it: median {:?}, slowest {:?}",
                        page + 1,
                        later.len(),
                        later[later.len() / 2],
                        later[later.len() - 1]
                    );
                }
                let started = std::time::Instant::now();
                let _ = app.tab().doc.as_ref().expect("open").session.render_page(page, PagifyApp::BACKGROUND_SAMPLE_SCALE);
                eprintln!("timing: {name} page {}: one render at the sampling scale {:?}", page + 1, started.elapsed());
            }
            let _ = std::fs::remove_dir_all(&dir);
        }
    }

    /// **A measurement, not a check: what an apply costs on the user's
    /// paragraph.** The 13-line paragraph of page 1 (57 objects) — one line
    /// retyped, then every line retyped (each reversed, so no letter the font
    /// lacks is needed, as the budget tests do), then both taken back with
    /// undo. Run alone: `cargo test -p pagify_app --release apply_timings --
    /// --ignored --nocapture`.
    #[test]
    #[ignore = "a measurement: run alone with --ignored --nocapture"]
    fn apply_timings() {
        if !std::path::Path::new(MARINA).is_file() {
            eprintln!("timing: skipping: the Marina datasheet is not on this machine");
            return;
        }
        let mut app = PagifyApp::new(Some(MARINA));
        let runs: HashMap<usize, TextRun> = text_runs(&app, 0).into_iter().map(|r| (r.object, r)).collect();
        let session = app.tab().doc.as_ref().expect("open").session.clone();
        for (what, every_line) in [("one line", false), ("every line", true)] {
            app.tab_mut().editing_run = None;
            app.pick_text_run(0, centre(&runs[&986].rect)).expect("picked");
            let edit = app.tab().editing_run.as_ref().expect("an editor opened").clone();
            let objects: usize = edit.lines.iter().map(|(o, _)| o.len()).sum();
            let typed: Vec<String> = edit
                .buffer
                .split('\n')
                .enumerate()
                .map(|(i, line)| {
                    if (every_line && !edit.frozen[i]) || i == 3 {
                        line.chars().rev().collect::<String>()
                    } else {
                        line.to_string()
                    }
                })
                .collect();
            app.tab_mut().editing_run.as_mut().expect("editing").buffer = typed.join("\n");
            let started = std::time::Instant::now();
            app.apply_editing_page();
            let applied = started.elapsed();
            let said = app.cmd.history().iter().last().map(|e| e.text.clone()).unwrap_or_default();
            let started = std::time::Instant::now();
            let (undone, _) = session.undo().expect("undo");
            eprintln!(
                "timing: retyping {what} of a 13-line, {objects}-object paragraph: apply {applied:?} ({said}); undo {:?} (undone: {undone})",
                started.elapsed()
            );
            app.tab_mut().doc.as_mut().expect("open").rendered_is_stale();
        }
    }

    // -- the census ------------------------------------------------------------

    /// What a click wrote to the log after byte `after`; moves `after` on.
    fn newest_pick_line(log: &std::path::Path, after: &mut u64) -> String {
        use std::io::{Read, Seek, SeekFrom};
        let mut file = std::fs::File::open(log).expect("the log file exists");
        file.seek(SeekFrom::Start(*after)).expect("seek");
        let mut tail = String::new();
        file.read_to_string(&mut tail).expect("read");
        *after += tail.len() as u64;
        tail.lines()
            .map(|l| serde_json::from_str::<serde_json::Value>(l).expect("valid json"))
            .filter(|l| l["kind"] == "pick")
            .map(|l| l["text"].as_str().unwrap_or_default().to_string())
            .last()
            .expect("the click wrote no pick line")
    }

    /// **A measurement, not a check: what clicking every word of a file opens.**
    ///
    /// Run on demand against any document —
    /// `PAGIFY_CENSUS_PDF=<file> PAGIFY_CENSUS_OUT=<file>.jsonl cargo test -p
    /// pagify_app --release paragraph_census -- --ignored --nocapture` — it
    /// clicks the middle of **every text object with area of every page** and
    /// writes one JSON line per click: the page (1-based), the object clicked
    /// and its words, the object the click actually resolved to (the smallest
    /// box under that point can be another), the way the click went
    /// (`block`, `single`, `joined`, `drawn`, `refused-rotated`, `none`),
    /// whether it opened, the message, the editor's lines as arrays of object
    /// ids with their frozen flags, the buffer, the object the box takes its
    /// look from, the time the click took, and the log line it wrote. Scoring
    /// the lines against hand-made labels is a separate job; this only reads
    /// the file the way a person with a mouse would.
    #[test]
    #[ignore = "a measurement: set PAGIFY_CENSUS_PDF and PAGIFY_CENSUS_OUT, then run with --ignored"]
    fn paragraph_census() {
        use std::io::Write;
        let pdf = std::env::var("PAGIFY_CENSUS_PDF").expect("PAGIFY_CENSUS_PDF: the file to click through");
        let out = std::env::var("PAGIFY_CENSUS_OUT").expect("PAGIFY_CENSUS_OUT: where to write the lines");
        let mut app = PagifyApp::new(Some(&pdf));
        assert!(app.tab().doc.is_some(), "{pdf} did not open");
        let (dir, log) = log_into(&mut app, "census");
        let mut sink = std::io::BufWriter::new(std::fs::File::create(&out).expect("PAGIFY_CENSUS_OUT is writable"));
        // All the pages, unless PAGIFY_CENSUS_PAGES names how many to do (from the first).
        let pages = app.tab().doc.as_ref().expect("open").page_count;
        let pages = std::env::var("PAGIFY_CENSUS_PAGES").ok().and_then(|n| n.parse().ok()).map_or(pages, |n: usize| pages.min(n));
        let mut after = 0u64;
        let mut total = 0usize;
        for page in 0..pages {
            // The seeds come from a reading made on the side, so the first click
            // on each page still pays for (and logs) the app's own: the cache
            // is not warmed for it.
            let snapshot = match app.tab().doc.as_ref().expect("open").session.page_text_snapshot(page) {
                Ok(snapshot) => snapshot,
                Err(why) => {
                    eprintln!("page {} could not be read: {why}", page + 1);
                    continue;
                }
            };
            let page_blocks = block_input::build_page_blocks(page, 0, 0, snapshot);
            let mut seeds: Vec<usize> = page_blocks.runs.keys().copied().collect();
            seeds.sort_unstable();
            for seed in seeds {
                let run = &page_blocks.runs[&seed];
                let at = centre(&run.rect);
                let resolved = block_input::pick_seed(&page_blocks, at.x as f32, at.y as f32, HIT_TOLERANCE_PT as f32)
                    .map(|(object, _)| object);
                app.tab_mut().editing_run = None;
                let started = std::time::Instant::now();
                let outcome = app.pick_text_run(page, at);
                let pick_ms = started.elapsed().as_secs_f32() * 1000.0;
                let line = newest_pick_line(&log, &mut after);
                let edit = app.tab().editing_run.as_ref();
                let record = serde_json::json!({
                    "page": page + 1,
                    "seed": seed,
                    "text": run.text,
                    "resolved_seed": resolved,
                    "path": field(&line, "path"),
                    "ok": outcome.is_ok(),
                    "message": outcome.as_ref().unwrap_or_else(|e| e),
                    "lines": edit.map(|e| e.lines.iter().map(|(objects, _)| objects.clone()).collect::<Vec<_>>()),
                    "frozen": edit.map(|e| e.frozen.clone()),
                    "buffer": edit.map(|e| e.buffer.clone()),
                    "look_object": edit.map(|e| e.look_object),
                    "pick_ms": pick_ms,
                    "log": line,
                });
                writeln!(sink, "{record}").expect("write a census line");
                total += 1;
            }
            eprintln!("census: page {} done ({total} clicks so far)", page + 1);
        }
        sink.flush().expect("flush");
        // Every block the editor's guard refused, and every page that could not
        // be read in one pass, said in words (content-free).
        let notes = logged(&log, "pick-note");
        for note in notes.iter().take(20) {
            eprintln!("census: note: {note}");
        }
        eprintln!("census: {} notes (blocks refused by the guard, pages not readable in one pass)", notes.len());
        let _ = std::fs::remove_dir_all(&dir);
        eprintln!("census: {total} clicks over {pages} pages, written to {out}");
    }
}
